/* DAWAH X — ahmad, অধ্যায় 28 · খণ্ড 28 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][28]=[[5401,5401,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُسْتَقْبِلٌ الْمَشْرِقَ يَقُولُ ‏ ‏أَلَا إِنَّ ‏ ‏الْفِتْنَةَ ‏ ‏هَاهُنَا أَلَا إِنَّ ‏ ‏الْفِتْنَةَ ‏ ‏هَاهُنَا مِنْ حَيْثُ يَطْلُعُ قَرْنُ الشَّيْطَانِ ‏","","",""],[5402,5402,"","","‏ ‏و قَالَ ‏ ‏أَحْمَد ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْبَهِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى ‏ ‏الْخُمْرَةِ ‏","","",""],[5403,5403,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ الْحَنَفِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏مَثَّلَ ‏ ‏بِذِي رُوحٍ ثُمَّ لَمْ يَتُبْ ‏ ‏مَثَّلَ ‏ ‏اللَّهُ بِهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[5404,5404,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏مُحَارِبِ بْنِ دِثَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّهَا النَّاسُ ‏ ‏اتَّقُوا الظُّلْمَ فَإِنَّهُ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ ‏","","",""],[5405,5405,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ مَسْعَدَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي الْعِيدَيْنِ ‏ ‏الْأَضْحَى وَالْفِطْرَ ثُمَّ يَخْطُبُ بَعْدَ الصَّلَاةِ ‏","","",""],[5406,5406,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عُثْمَانَ يَعْنِي ابْنَ الْمُغِيرَةِ وَهُوَ الْأَعْشَى ‏ ‏عَنْ ‏ ‏مُهَاجِرٍ الشَّامِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَبِسَ ثَوْبَ ‏ ‏شُهْرَةٍ ‏ ‏فِي الدُّنْيَا أَلْبَسَهُ اللَّهُ ثَوْبَ مَذَلَّةٍ يَوْمَ الْقِيَامَةِ ‏","","",""],[5407,5407,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَاصِمٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ فِي ‏ ‏ثَقِيفٍ ‏ ‏كَذَّابًا ‏ ‏وَمُبِيرًا ‏","","",""],[5408,5408,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدِمَ يَوْمَ ‏ ‏أُحُدٍ ‏ ‏فَسَمِعَ نِسَاءً مِنْ ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏يَبْكِينَ عَلَى هَلْكَاهُنَّ فَقَالَ لَكِنْ ‏ ‏حَمْزَةُ ‏ ‏لَا ‏ ‏بَوَاكِيَ ‏ ‏لَهُ فَجِئْنَ نِسَاءُ ‏ ‏الْأَنْصَارِ ‏ ‏يَبْكِينَ عَلَى ‏ ‏حَمْزَةَ ‏ ‏عِنْدَهُ فَاسْتَيْقَظَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُنَّ يَبْكِينَ فَقَالَ يَا ‏ ‏وَيْحَهُنَّ ‏ ‏أَنْتُنَّ هَاهُنَا تَبْكِينَ حَتَّى الْآنَ مُرُوهُنَّ فَلْيَرْجِعْنَ وَلَا يَبْكِينَ عَلَى هَالِكٍ بَعْدَ الْيَوْمِ ‏","","",""],[5409,5409,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ ثَابِتِ بْنِ ثَوْبَانَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَّانُ بْنُ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي مُنِيبٍ الْجُرَشِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بُعِثْتُ بَيْنَ يَدَيْ السَّاعَةِ بِالسَّيْفِ حَتَّى يُعْبَدَ اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَجُعِلَ رِزْقِي تَحْتَ ظِلِّ رُمْحِي وَجُعِلَ الذُّلُّ وَالصَّغَارُ عَلَى مَنْ خَالَفَ أَمْرِي وَمَنْ تَشَبَّهَ بِقَوْمٍ فَهُوَ مِنْهُمْ ‏","","",""],[5410,5410,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَرَّتْ بِنَا جِنَازَةٌ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لَوْ قُمْتَ بِنَا مَعَهَا قَالَ فَأَخَذَ بِيَدِي فَقَبَضَ عَلَيْهَا قَبْضًا شَدِيدًا فَلَمَّا دَنَوْنَا مِنْ الْمَقَابِرِ سَمِعَ ‏ ‏رَنَّةً ‏ ‏مِنْ خَلْفِهِ وَهُوَ قَابِضٌ عَلَى يَدِي فَاسْتَدَارَنِي فَاسْتَقْبَلَهَا فَقَالَ لَهَا شَرًّا وَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تُتْبَعَ جِنَازَةٌ مَعَهَا ‏ ‏رَانَّةٌ ‏","","",""],[5411,5411,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَكَانَ ‏ ‏عُمَرُ ‏ ‏يَأْمُرُنَا بِالْمُقَامِ عَلَيْهِمَا مِنْ حَيْثُ ‏ ‏يَرَاهُمَا ‏","","",""],[5412,5412,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ فِيمَا دُونَ خَمْسٍ مِنْ الْإِبِلِ وَلَا خَمْسِ ‏ ‏أَوَاقٍ ‏ ‏وَلَا خَمْسَةِ ‏ ‏أَوْسَاقٍ ‏ ‏صَدَقَةٌ ‏","","",""],[5413,5413,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَقِيلٍ يَعْنِي عَبْدَ اللَّهِ بْنَ عَقِيلٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ يَزِيدَ الثُّمَالِيِّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الْعَجْلَانِ الْمُحَارِبِيُّ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْكَافِرَ لَيَجُرُّ لِسَانَهُ يَوْمَ الْقِيَامَةِ وَرَاءَهُ قَدْرَ ‏ ‏فَرْسَخَيْنِ ‏ ‏يَتَوَطَّؤُهُ ‏ ‏النَّاسُ ‏","","",""],[5414,5414,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَقِيلٍ ‏ ‏عَنْ ‏ ‏بَرَكَةَ بْنِ يَعْلَى التَّيْمِيِّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سُوَيْدٍ الْعَبْدِيُّ ‏ ‏قَالَ ‏ ‏أَتَيْنَا ‏ ‏ابْنَ عُمَرَ ‏ ‏فَجَلَسْنَا بِبَابِهِ لِيُؤْذَنَ لَنَا فَأَبْطَأَ عَلَيْنَا الْإِذْنُ قَالَ فَقُمْتُ إِلَى جُحْرٍ فِي الْبَابِ فَجَعَلْتُ أَطَّلِعُ فِيهِ ‏ ‏فَفَطِنَ ‏ ‏بِي فَلَمَّا ‏ ‏أَذِنَ لَنَا جَلَسْنَا فَقَالَ أَيُّكُمْ اطَّلَعَ آنِفًا فِي دَارِي قَالَ قُلْتُ أَنَا قَالَ بِأَيِّ شَيْءٍ اسْتَحْلَلْتَ أَنْ تَطَّلِعَ فِي دَارِي قَالَ قُلْتُ أَبْطَأَ عَلَيْنَا الْإِذْنُ فَنَظَرْتُ فَلَمْ أَتَعَمَّدْ ذَلِكَ قَالَ ثُمَّ سَأَلُوهُ عَنْ أَشْيَاءَ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ ‏ ‏شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَحَجِّ ‏ ‏الْبَيْتِ ‏ ‏وَصِيَامِ رَمَضَانَ قُلْتُ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏مَا تَقُولُ فِي الْجِهَادِ قَالَ مَنْ جَاهَدَ فَإِنَّمَا يُجَاهِدُ لِنَفْسِهِ ‏","","",""],[5415,5415,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَقِيلٍ وَهُوَ عَبْدُ اللَّهِ بْنُ عَقِيلٍ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ حَمْزَةَ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سَالِمٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رُبَّمَا ذَكَرْتُ قَوْلَ الشَّاعِرِ وَأَنَا أَنْظُرُ إِلَى وَجْهِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ ‏ ‏يَسْتَسْقِي فَمَا يَنْزِلُ حَتَّى ‏ ‏يَجِيشَ ‏ ‏كُلُّ ‏ ‏مِيزَابٍ ‏ ‏وَأَذْكُرُ قَوْلَ الشَّاعِرِ ‏ ‏وَأَبْيَضَ يُسْتَسْقَى ‏ ‏الْغَمَامُ ‏ ‏بِوَجْهِهِ ‏ ‏ثِمَالُ ‏ ‏الْيَتَامَى ‏ ‏عِصْمَةٌ ‏ ‏لِلْأَرَامِلِ ‏ ‏وَهُوَ قَوْلُ ‏ ‏أَبِي طَالِبٍ ‏","","",""],[5416,5416,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَقِيلٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَهُوَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَقِيلٍ ‏ ‏صَالِحُ الْحَدِيثِ ثِقَةٌ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ حَمْزةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ الْعَنْ فُلَانًا اللَّهُمَّ الْعَنْ ‏ ‏الْحَارِثَ بْنَ هِشَامٍ ‏ ‏اللَّهُمَّ الْعَنْ ‏ ‏سُهَيْلَ بْنَ عَمْرٍو ‏ ‏اللَّهُمَّ الْعَنْ ‏ ‏صَفْوَانَ بْنَ أُمَيَّةَ ‏ ‏قَالَ فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏لَيْسَ لَكَ مِنْ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ ‏} ‏قَالَ فَتِيبَ عَلَيْهِمْ كُلِّهِمْ ‏","","",""],[5417,5417,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيٌّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي يَعْقُوبَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نُعْمٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏وَأَنَا جَالِسٌ فَسَأَلَهُ عَنْ دَمِ الْبَعُوضِ فَقَالَ لَهُ مِمَّنْ أَنْتَ قَالَ مِنْ أَهْلِ ‏ ‏الْعِرَاقِ ‏ ‏قَالَ هَا انْظُرُوا إِلَى هَذَا يَسْأَلُ عَنْ دَمِ الْبَعُوضِ وَقَدْ قَتَلُوا ابْنَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏هُمَا رَيْحَانَتِي مِنْ الدُّنْيَا ‏","","",""],[5418,5418,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏نَزَعَ ‏ ‏يَدَهُ مِنْ الطَّاعَةِ فَلَا حُجَّةَ لَهُ يَوْمَ الْقِيَامَةِ وَمَنْ مَاتَ مُفَارِقًا لِلْجَمَاعَةِ مَاتَ مِيتَةً جَاهِلِيَّةً ‏","","",""],[5419,5419,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ مُحَمَّدِ بْنِ زَيْدِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُ هَذَا الْأَمْرُ فِي ‏ ‏قُرَيْشٍ ‏ ‏مَا بَقِيَ مِنْ النَّاسِ اثْنَانِ ‏","","",""],[5420,5420,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ أَبِي الصَّهْبَاءِ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَادَى فِي النَّاسِ الصَّلَاةُ ‏ ‏جَامِعَةٌ ‏ ‏فَبَلَغَ ذَلِكَ ‏ ‏عَبْدَ اللَّهِ ‏ ‏فَانْطَلَقَ إِلَى أَهْلِهِ جَوَادًا فَأَلْقَى ثِيَابًا كَانَتْ عَلَيْهِ وَلَبِسَ ثِيَابًا كَانَ يَأْتِي فِيهَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ انْطَلَقَ إِلَى الْمُصَلَّى وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ انْحَدَرَ مِنْ مِنْبَرِهِ وَقَامَ ‏ ‏النَّاسُ ‏ ‏فِي وَجْهِهِ فَقَالَ مَا أَحْدَثَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْيَوْمَ قَالُوا ‏ ‏نَهَى عَنْ ‏ ‏النَّبِيذِ ‏ ‏قَالَ أَيُّ ‏ ‏النَّبِيذِ ‏ ‏قَالَ نَهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏ ‏قَالَ فَقُلْتُ ‏ ‏لِنَافِعٍ ‏ ‏فَالْجَرَّةُ ‏ ‏قَالَ وَمَا ‏ ‏الْجَرَّةُ ‏ ‏قَالَ قُلْتُ ‏ ‏الْحَنْتَمَةُ ‏ ‏قَالَ وَمَا ‏ ‏الْحَنْتَمَةُ ‏ ‏قُلْتُ ‏ ‏الْقُلَّةُ ‏ ‏قَالَ لَا قُلْتُ ‏ ‏فَالْمُزَفَّتُ ‏ ‏قَالَ وَمَا ‏ ‏الْمُزَفَّتُ ‏ ‏قُلْتُ ‏ ‏الزِّقُّ ‏ ‏يُزَفَّتُ ‏ ‏وَالرَّاقُودُ ‏ ‏يُزَفَّتُ ‏ ‏قَالَ لَا لَمْ يَنْهَ يَوْمَئِذٍ إِلَّا عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏","","",""],[5421,5421,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏عُقْبَةُ يَعْنِي ابْنَ أَبِي الصَّهْبَاءِ ‏ ‏حَدَّثَنَا ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّهُ كَانَ ذَاتَ يَوْمٍ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَ ‏ ‏نَفَرٍ ‏ ‏مِنْ أَصْحَابِهِ فَأَقْبَلَ عَلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏يَا هَؤُلَاءِ أَلَسْتُمْ تَعْلَمُونَ أَنِّي رَسُولُ اللَّهِ إِلَيْكُمْ قَالُوا بَلَى نَشْهَدُ أَنَّكَ رَسُولُ اللَّهِ قَالَ أَلَسْتُمْ تَعْلَمُونَ أَنَّ اللَّهَ أَنْزَلَ فِي كِتَابِهِ مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ قَالُوا بَلَى نَشْهَدُ أَنَّهُ مَنْ أَطَاعَكَ فَقَدْ أَطَاعَ اللَّهَ وَأَنَّ مِنْ طَاعَةِ اللَّهِ طَاعَتَكَ قَالَ فَإِنَّ مِنْ طَاعَةِ اللَّهِ أَنْ تُطِيعُونِي وَإِنَّ مِنْ طَاعَتِي أَنْ تُطِيعُوا أَئِمَّتَكُمْ أَطِيعُوا أَئِمَّتَكُمْ فَإِنْ صَلَّوْا قُعُودًا فَصَلُّوا قُعُودًا ‏","","",""],[5422,5422,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْمَسْأَلَةُ ‏ ‏كُدُوحٌ ‏ ‏فِي وَجْهِ صَاحِبِهَا يَوْمَ الْقِيَامَةِ فَمَنْ بَدَنَ فَلْيَسْتَبْقِ عَلَى وَجْهِهِ وَأَهْوَنُ الْمَسْأَلَةِ مَسْأَلَةُ ذِي الرَّحِمِ تَسْأَلُهُ فِي حَاجَةٍ وَخَيْرُ الْمَسْأَلَةِ الْمَسْأَلَةُ عَنْ ‏ ‏ظَهْرِ غِنًى ‏ ‏وَابْدَأْ بِمَنْ ‏ ‏تَعُولُ ‏","","",""],[5423,5423,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَنْ يَزَالَ الْمَرْءُ فِي فُسْحَةٍ مِنْ دِينِهِ مَا لَمْ يُصِبْ دَمًا حَرَامًا ‏","","",""],[5424,5424,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏ابْنُ عُمَرَ ‏ ‏عَلَى ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏وَغُلَامٌ مِنْ بَنِيهِ ‏ ‏رَابِطٌ ‏ ‏دَجَاجَةً يَرْمِيهَا فَمَشَى إِلَى الدَّجَاجَةِ ‏ ‏فَحَلَّهَا ‏ ‏ثُمَّ أَقْبَلَ بِهَا وَبِالْغُلَامِ وَقَالَ ‏ ‏لِيَحْيَى ‏ ‏ازْجُرُوا ‏ ‏غُلَامَكُمْ هَذَا مِنْ أَنْ ‏ ‏يَصْبِرَ ‏ ‏هَذَا الطَّيْرَ عَلَى الْقَتْلِ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى أَنْ ‏ ‏تُصْبَرَ ‏ ‏بَهْمَةٌ ‏ ‏أَوْ غَيْرُهَا لِقَتْلٍ وَإِنْ أَرَدْتُمْ ذَبْحَهَا فَاذْبَحُوهَا ‏","","",""],[5425,5425,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنِي ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمَيَّةَ بْنِ عَبْدِ اللَّهِ بْنِ خَالِدِ بْنِ أَسِيدٍ ‏ ‏أَنَّهُ ‏ ‏قَالَ ‏ ‏لِعَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏إِنَّا ‏ ‏نَجِدُ صَلَاةَ الْحَضَرِ وَصَلَاةَ الْخَوْفِ فِي الْقُرْآنِ وَلَا نَجِدُ صَلَاةَ السَّفَرِ فِي الْقُرْآنِ فَقَالَ لَهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏ابْنَ أَخِي إِنَّ اللَّهَ عَزَّ وَجَلَّ بَعَثَ إِلَيْنَا ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا نَعْلَمُ شَيْئًا فَإِنَّمَا نَفْعَلُ كَمَا رَأَيْنَا ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُ ‏","","",""],[5426,5426,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ يَمْدَحُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ فَجَعَلَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَقُولُ هَكَذَا ‏ ‏يَحْثُو ‏ ‏فِي وَجْهِهِ التُّرَابَ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا رَأَيْتُمْ الْمَدَّاحِينَ ‏ ‏فَاحْثُوا ‏ ‏فِي وُجُوهِهِمْ التُّرَابَ ‏","","",""],[5427,5427,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ فِي خَاتَمِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ ‏","","",""],[5428,5428,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ لِلنَّبِيِّ مُؤَذِّنَانِ ‏","","",""],[5429,5429,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏قَدِمَ ‏ ‏رَجُلَانِ ‏ ‏مِنْ الْمَشْرِقِ خَطِيبَانِ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَا فَتَكَلَّمَا ثُمَّ قَعَدَا وَقَامَ ‏ ‏ثَابِتُ بْنُ قَيْسٍ ‏ ‏خَطِيبُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَكَلَّمَ ثُمَّ قَعَدَ فَعَجِبَ النَّاسُ مِنْ كَلَامِهِمْ فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏قُولُوا بِقَوْلِكُمْ فَإِنَّمَا ‏ ‏تَشْقِيقُ ‏ ‏الْكَلَامِ مِنْ الشَّيْطَانِ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ ‏ ‏الْبَيَانِ ‏ ‏سِحْرًا ‏","","",""],[5430,5430,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ ‏ ‏إِذَا انْصَرَفَ مِنْ الْجُمُعَةِ انْصَرَفَ إِلَى مَنْزِلِهِ فَسَجَدَ سَجْدَتَيْنِ وَذَكَرَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُ ذَلِكَ ‏","","",""],[5431,5431,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكُ بْنُ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏جُنَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لِجَهَنَّمَ سَبْعَةُ أَبْوَابٍ بَابٌ مِنْهَا لِمَنْ ‏ ‏سَلَّ ‏ ‏سَيْفَهُ عَلَى أُمَّتِي ‏ ‏أَوْ قَالَ أُمَّةِ ‏ ‏مُحَمَّدٍ ‏","","",""],[5432,5432,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ يَعْنِي الطَّحَّانَ ‏ ‏حَدَّثَنَا ‏ ‏بَيَانٌ ‏ ‏عَنْ ‏ ‏وَبَرَةَ ‏ ‏عَنِ ‏ ‏ابْنِ جُبَيْرٍ يَعْنِي سَعِيدًا ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏خَرَجَ إِلَيْنَا ‏ ‏ابْنُ عُمَرَ ‏ ‏وَنَحْنُ نَرْجُو أَنْ يُحَدِّثَنَا بِحَدِيثٍ يُعْجِبُنَا فَبَدَرَنَا إِلَيْهِ رَجُلٌ فَقَالَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏مَا تَقُولُ فِي الْقِتَالِ فِي ‏ ‏الْفِتْنَةِ ‏ ‏فَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَالَ ‏ { ‏وَقَاتِلُوهُمْ حَتَّى لَا تَكُونَ ‏ ‏فِتْنَةٌ ‏ } ‏قَالَ ‏ ‏وَيْحَكَ ‏ ‏أَتَدْرِي مَا ‏ ‏الْفِتْنَةُ ‏ ‏إِنَّمَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَاتِلُ الْمُشْرِكِينَ وَكَانَ الدُّخُولُ فِي دِينِهِمْ ‏ ‏فِتْنَةً ‏ ‏وَلَيْسَ بِقِتَالِكُمْ عَلَى الْمُلْكِ ‏","","",""],[5433,5433,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَمَقْتُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرًا فَكَانَ ‏ ‏يَقْرَأُ فِي الرَّكْعَتَيْنِ قَبْلَ الْفَجْرِ ‏ ‏قُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏وَقُلْ هُوَ اللَّهُ أَحَدٌ ‏","","",""],[5434,5434,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏فُضَيلٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَخَّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْعِشَاءِ ‏ ‏حَتَّى نَامَ النَّاسُ ‏ ‏وَتَهَجَّدَ ‏ ‏الْمُتَهَجِّدُونَ ‏ ‏وَاسْتَيْقَظَ الْمُسْتَيْقِظُ فَخَرَجَ فَأُقِيمَتْ الصَّلَاةُ وَقَالَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَخَّرْتُهَا إِلَى هَذَا الْوَقْتِ ‏","","",""],[5435,5435,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ يَعْنِي ابْنَ عَقِيلٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَسَاهُ ‏ ‏حُلَّةً ‏ ‏سِيَرَاءَ ‏ ‏وَكَسَا ‏ ‏أُسَامَةَ ‏ ‏قُبْطِيَّتَيْنِ ثُمَّ قَالَ ‏ ‏مَا مَسَّ الْأَرْضَ فَهُوَ فِي النَّارِ ‏","","",""],[5436,5436,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ إِيَادِ بْنِ لَقِيطٍ ‏ ‏حَدَّثَنَا ‏ ‏إِيَادٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ نُعْمٍ ‏ ‏أَوْ ‏ ‏نُعَيْمٍ الْأَعْرَجِيِّ ‏ ‏شَكَّ ‏ ‏أَبُو الْوَلِيدِ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ ‏ ‏الْمُتْعَةِ ‏ ‏وَأَنَا عِنْدَهُ ‏ ‏مُتْعَةِ ‏ ‏النِّسَاءِ ‏ ‏فَقَالَ وَاللَّهِ مَا كُنَّا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَانِينَ وَلَا ‏ ‏مُسَافِحِينَ ‏ ‏ثُمَّ قَالَ وَاللَّهِ لَقَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيَكُونَنَّ قَبْلَ يَوْمِ الْقِيَامَةِ ‏ ‏الْمَسِيحُ الدَّجَّالُ ‏ ‏وَكَذَّابُونَ ثَلَاثُونَ أَوْ أَكْثَرُ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ إِيَادِ بْنِ لَقِيطٍ ‏ ‏أَخْبَرَنَا ‏ ‏إِيَادٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَلَمْ يَشُكَّ فِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[5437,5437,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏خَارِجَةُ بْنُ عَبْدِ اللَّهِ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ أَعِزَّ الْإِسْلَامَ بِأَحَبِّ هَذَيْنِ الرَّجُلَيْنِ إِلَيْكَ ‏ ‏بِأَبِي جَهْلٍ ‏ ‏أَوْ ‏ ‏بِعُمَرَ بْنِ الْخَطَّابِ ‏ ‏فَكَانَ أَحَبُّهُمَا إِلَى اللَّهِ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏","","",""],[5438,5438,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏خَارِجَةُ بْنُ عَبْدِ اللَّهِ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ جَعَلَ الْحَقَّ عَلَى قَلْبِ ‏ ‏عُمَرَ ‏ ‏وَلِسَانِهِ ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏مَا نَزَلَ بِالنَّاسِ أَمْرٌ قَطُّ فَقَالُوا فِيهِ وَقَالَ فِيهِ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏أَوْ قَالَ ‏ ‏عُمَرُ ‏ ‏إِلَّا نَزَلَ الْقُرْآنُ عَلَى نَحْوٍ مِمَّا قَالَ ‏ ‏عُمَرُ ‏","","",""],[5439,5439,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏مَطَرٌ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَافَرْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَ ‏ ‏عُمَرَ ‏ ‏فَكَانَا لَا يَزِيدَانِ عَلَى رَكْعَتَيْنِ وَكُنَّا ضُلَّالًا فَهَدَانَا اللَّهُ بِهِ فَبِهِ نَقْتَدِي ‏","","",""],[5440,5440,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَمَقْتُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعًا وَعِشْرِينَ مَرَّةً ‏ ‏أَوْ خَمْسًا وَعِشْرِينَ مَرَّةً ‏ ‏يَقْرَأُ فِي الرَّكْعَتَيْنِ قَبْلَ الْفَجْرِ وَبَعْدَ الْمَغْرِبِ ‏ ‏قُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏وَقُلْ هُوَ اللَّهُ أَحَدٌ ‏","","",""],[5441,5441,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ أَبِي الْأَخْضَرِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏يُفْتِي بِالَّذِي أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ مِنْ الرُّخْصَةِ ‏ ‏بِالتَّمَتُّعِ ‏ ‏وَسَنَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ فَيَقُولُ نَاسٌ ‏ ‏لِابْنِ عُمَرَ ‏ ‏كَيْفَ تُخَالِفُ أَبَاكَ وَقَدْ نَهَى عَنْ ذَلِكَ فَيَقُولُ لَهُمْ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَيْلَكُمْ أَلَا تَتَّقُونَ اللَّهَ إِنْ كَانَ ‏ ‏عُمَرُ ‏ ‏نَهَى عَنْ ذَلِكَ ‏ ‏فَيَبْتَغِي فِيهِ الْخَيْرَ يَلْتَمِسُ بِهِ تَمَامَ الْعُمْرَةِ فَلِمَ تُحَرِّمُونَ ذَلِكَ وَقَدْ أَحَلَّهُ اللَّهُ وَعَمِلَ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَقُّ أَنْ تَتَّبِعُوا سُنَّتَهُ أَمْ سُنَّةَ ‏ ‏عُمَرَ ‏ ‏إِنَّ ‏ ‏عُمَرَ ‏ ‏لَمْ يَقُلْ لَكُمْ إِنَّ الْعُمْرَةَ فِي أَشْهُرِ الْحَجِّ حَرَامٌ وَلَكِنَّهُ قَالَ ‏ ‏إِنَّ أَتَمَّ الْعُمْرَةِ أَنْ تُفْرِدُوهَا مِنْ أَشْهُرِ الْحَجِّ ‏","","",""],[5442,5442,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَرَاكَ تُزَاحِمُ عَلَى هَذَيْنِ الرُّكْنَيْنِ قَالَ إِنْ أَفْعَلْ فَقَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مَسْحَهُمَا ‏ ‏يَحُطَّانِ ‏ ‏الْخَطَايَا ‏","","",""],[5443,5443,"","","‏ ‏قَالَ ‏ ‏وَسَمِعْتُهُ يَقُولُ ‏ ‏مَنْ طَافَ بِهَذَا ‏ ‏الْبَيْتِ ‏ ‏أُسْبُوعًا ‏ ‏يُحْصِيهِ ‏ ‏كُتِبَ لَهُ بِكُلِّ خُطْوَةٍ حَسَنَةٌ وَكُفِّرَ عَنْهُ سَيِّئَةٌ وَرُفِعَتْ لَهُ دَرَجَةٌ وَكَانَ ‏ ‏عَدْلَ ‏ ‏عِتْقِ رَقَبَةٍ ‏","","",""],[5444,5444,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ عَيَّاشٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ قُعَيْسٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَيَكُونُ عَلَيْكُمْ أُمَرَاءُ يَأْمُرُونَكُمْ بِمَا لَا يَفْعَلُونَ فَمَنْ صَدَّقَهُمْ بِكِذْبِهِمْ وَأَعَانَهُمْ عَلَى ظُلْمِهِمْ فَلَيْسَ مِنِّي وَلَسْتُ مِنْهُ وَلَنْ ‏ ‏يَرِدَ ‏ ‏عَلَيَّ الْحَوْضَ ‏","","",""],[5445,5445,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ شَاذَانُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَأَلَكُمْ بِاللَّهِ فَأَعْطُوهُ وَمَنْ دَعَاكُمْ فَأَجِيبُوهُ وَمَنْ أَهْدَى لَكُمْ فَكَافِئُوهُ فَإِنْ لَمْ تَجِدُوا مَا تُكَافِئُوهُ فَادْعُوا لَهُ ‏","","",""],[5446,5446,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَنْظَلَةُ ‏ ‏سَمِعْتُ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَأَنْ يَكُونَ جَوْفُ الْمَرْءِ مَمْلُوءًا ‏ ‏قَيْحًا ‏ ‏خَيْرٌ لَهُ مِنْ أَنْ يَكُونَ مَمْلُوءًا شِعْرًا ‏","","",""],[5447,5447,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏سَمِعْتُ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَدْخُلُوا مَسَاكِنَ الَّذِينَ ظَلَمُوا أَنْفُسَهُمْ إِلَّا أَنْ تَكُونُوا بَاكِينَ أَنْ يُصِيبَكُمْ مِثْلُ مَا أَصَابَهُمْ ‏","","",""],[5448,5448,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمٌ مِنْ ذَهَبٍ كَانَ يُدْخِلُ فَصَّهُ فِي بَاطِنِ كَفِّهِ ‏ ‏فَطَرَحَهُ ‏ ‏ذَاتَ يَوْمٍ ‏ ‏فَطَرَحَ ‏ ‏أَصْحَابُهُ خَوَاتِيمَهُمْ ثُمَّ اتَّخَذَ خَاتَمًا مِنْ فِضَّةٍ وَكَانَ يَخْتِمُ بِهِ وَلَا يَلْبَسُهُ ‏","","",""],[5449,5449,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُسَامَةُ ‏ ‏أَحَبُّ النَّاسِ إِلَيَّ مَا ‏ ‏حَاشَا ‏ ‏فَاطِمَةَ ‏ ‏وَلَا غَيْرَهَا ‏","","",""],[5450,5450,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏رَقَبَةَ ‏ ‏عَنْ ‏ ‏عَوْنِ بْنِ أَبِي جُحَيْفَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سُمَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ أَمْشِي مَعَ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏فَإِذَا نَحْنُ بِرَأْسٍ مَنْصُوبٍ عَلَى خَشَبَةٍ قَالَ فَقَالَ شَقِيَ قَاتِلُ هَذَا قَالَ قُلْتُ أَنْتَ تَقُولُ هَذَا يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ فَشَدَّ يَدَهُ مِنْ يَدِي وَقَالَ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا مَشَى الرَّجُلُ مِنْ أُمَّتِي إِلَى الرَّجُلِ لِيَقْتُلَهُ فَلْيَقُلْ هَكَذَا فَالْمَقْتُولُ فِي الْجَنَّةِ وَالْقَاتِلُ فِي النَّارِ ‏","","",""],[5451,5451,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏صَخْرٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏جَمَعَ بَنِيهِ حِينَ ‏ ‏انْتَزَى ‏ ‏أَهْلُ ‏ ‏الْمَدِينَةِ ‏ ‏مَعَ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏وَخَلَعُوا ‏ ‏يَزِيدَ بْنَ مُعَاوِيَةَ ‏ ‏فَقَالَ إِنَّا قَدْ ‏ ‏بَايَعْنَا ‏ ‏هَذَا الرَّجُلَ ‏ ‏بِبَيْعِ ‏ ‏اللَّهِ وَرَسُولِهِ وَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْغَادِرُ يُنْصَبُ لَهُ ‏ ‏لِوَاءٌ ‏ ‏يَوْمَ الْقِيَامَةِ فَيُقَالُ هَذِهِ ‏ ‏غَدْرَةُ ‏ ‏فُلَانٍ وَإِنَّ مِنْ أَعْظَمِ الْغَدْرِ إِلَّا أَنْ يَكُونَ الْإِشْرَاكُ بِاللَّهِ تَعَالَى أَنْ ‏ ‏يُبَايِعَ ‏ ‏الرَّجُلُ رَجُلًا عَلَى ‏ ‏بَيْعِ ‏ ‏اللَّهِ وَرَسُولِهِ ثُمَّ ‏ ‏يَنْكُثَ ‏ ‏بَيْعَتَهُ ‏ ‏فَلَا يَخْلَعَنَّ أَحَدٌ مِنْكُمْ ‏ ‏يَزِيدَ ‏ ‏وَلَا يُسْرِفَنَّ أَحَدٌ مِنْكُمْ فِي هَذَا الْأَمْرِ فَيَكُونَ ‏ ‏صَيْلَمًا ‏ ‏فِيمَا بَيْنِي وَبَيْنَكُمْ ‏","","",""],[5452,5452,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏أَنَّ ‏ ‏أَبَا الْمَلِيحِ ‏ ‏قَالَ ‏ ‏لِأَبِي قِلَابَةَ ‏ ‏دَخَلْتُ أَنَا وَأَبُوكَ عَلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏فَحَدَّثَنَا أَنَّهُ دَخَلَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَلْقَى لَهُ وَسَادَةً مِنْ ‏ ‏أَدَمٍ ‏ ‏حَشْوُهَا لِيفٌ ‏ ‏وَلَمْ ‏ ‏أَقْعُدْ عَلَيْهَا بَقِيَتْ بَيْنِي وَبَيْنَهُ ‏","","",""],[5453,5453,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ ‏ ‏أَفْرَى ‏ ‏الْفِرَى ‏ ‏أَنْ يُرِيَ عَيْنَيْهِ فِي الْمَنَامِ مَا لَمْ تَرَيَا ‏","","",""],[5454,5454,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْكَرِيمُ ابْنُ الْكَرِيمِ ابْنِ الْكَرِيمِ ابْنِ الْكَرِيمِ ‏ ‏يُوسُفُ بْنُ يَعْقُوبَ بْنِ إِسْحَاقَ بْنِ إِبْرَاهِيمَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِمْ وَسَلَّمَ ‏","","",""],[5455,5455,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَسَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُلَّةً ‏ ‏مِنْ ‏ ‏حُلَلِ ‏ ‏السِّيَرَاءِ ‏ ‏أَهْدَاهَا لَهُ ‏ ‏فَيْرُوزُ ‏ ‏فَلَبِسْتُ ‏ ‏الْإِزَارَ ‏ ‏فَأَغْرَقَنِي طُولًا وَعَرْضًا فَسَحَبْتُهُ وَلَبِسْتُ الرِّدَاءَ ‏ ‏فَتَقَنَّعْتُ ‏ ‏بِهِ فَأَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَاتِقِي فَقَالَ يَا ‏ ‏عَبْدَ اللَّهِ ‏ ‏ارْفَعْ الْإِزَارَ فَإِنَّ مَا مَسَّتْ الْأَرْضُ مِنْ الْإِزَارِ إِلَى مَا أَسْفَلَ مِنْ الْكَعْبَيْنِ فِي النَّارِ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏فَلَمْ أَرَ إِنْسَانًا قَطُّ أَشَدَّ تَشْمِيرًا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏","","",""],[5456,5456,"","","‏ ‏حَدَّثَنَا ‏ ‏مُهَنَّأُ بْنُ عَبْدِ الْحَمِيدِ أَبُو شِبْلٍ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَسَاهُ ‏ ‏حُلَّةً ‏ ‏فَأَسْبَلَهَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ قَوْلًا شَدِيدًا وَذَكَرَ النَّارَ ‏","","",""],[5457,5457,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُغِيرَةِ بْنِ حُنَيْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَذْهَبًا مُوَاجِهَ الْقِبْلَةِ ‏","","",""],[5458,5458,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ وَائِلٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَعَنَ اللَّهُ الْخَمْرَ وَلَعَنَ شَارِبَهَا وَسَاقِيَهَا وَعَاصِرَهَا وَمُعْتَصِرَهَا وَبَائِعَهَا ‏ ‏وَمُبْتَاعَهَا ‏ ‏وَحَامِلَهَا وَالْمَحْمُولَةَ إِلَيْهِ وَآكِلَ ثَمَنِهَا ‏","","",""],[5459,5459,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ يَصْبُغُ ثِيَابَهُ وَيَدَّهِنُ بِالزَّعْفَرَانِ فَقِيلَ لَهُ ‏ ‏لِمَ تَصْبُغُ ثِيَابَكَ وَتَدَّهِنُ بِالزَّعْفَرَانِ قَالَ لِأَنِّي رَأَيْتُهُ أَحَبَّ الْأَصْبَاغِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَّهِنُ بِهِ وَيَصْبُغُ بِهِ ثِيَابَهُ ‏","","",""],[5460,5460,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَتَى ‏ ‏ابْنَ مُطِيعٍ ‏ ‏لَيَالِي ‏ ‏الْحَرَّةِ ‏ ‏فَقَالَ ضَعُوا ‏ ‏لِأَبِي عَبْدِ الرَّحْمَنِ ‏ ‏وِسَادَةً فَقَالَ إِنِّي لَمْ آتِ لِأَجْلِسَ إِنَّمَا جِئْتُ لِأُخْبِرَكَ كَلِمَتَيْنِ سَمِعْتُهُمَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ نَزَعَ يَدًا مِنْ طَاعَةٍ لَمْ تَكُنْ لَهُ حُجَّةٌ يَوْمَ الْقِيَامَةِ وَمَنْ مَاتَ مُفَارِقًا لِلْجَمَاعَةِ فَإِنَّهُ يَمُوتُ مَوْتَ الْجَاهِلِيَّةِ ‏","","",""],[5461,5461,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادٌ يَعْنِي ابْنَ عَبَّادٍ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَهْلَلْنَا ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحَجِّ ‏ ‏مُفْرَدًا ‏","","",""],[5462,5462,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ صَالِحٍ ‏ ‏وَاسْمُهُ الَّذِي يُعْرَفُ بِهِ ‏ ‏نُعَيْمُ بْنُ النَّحَّامِ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمَّاهُ ‏ ‏صَالِحًا ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏لِعُمَرَ بْنِ الْخَطَّابِ ‏ ‏اخْطُبْ عَلَيَّ ابْنَةَ ‏ ‏صَالِحٍ ‏ ‏فَقَالَ إِنَّ لَهُ يَتَامَى وَلَمْ يَكُنْ لِيُؤْثِرَنَا عَلَيْهِمْ فَانْطَلَقَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِلَى عَمِّهِ ‏ ‏زَيْدِ بْنِ الْخَطَّابِ ‏ ‏لِيَخْطُبَ فَانْطَلَقَ ‏ ‏زَيْدٌ ‏ ‏إِلَى ‏ ‏صَالِحٍ ‏ ‏فَقَالَ إِنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَرْسَلَنِي إِلَيْكَ يَخْطُبُ ابْنَتَكَ فَقَالَ لِي يَتَامَى وَلَمْ أَكُنْ ‏ ‏لِأُتْرِبَ ‏ ‏لَحْمِي وَأَرْفَعَ لَحْمَكُمْ أُشْهِدُكُمْ أَنِّي قَدْ أَنْكَحْتُهَا فُلَانًا وَكَانَ هَوَى أُمِّهَا إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏فَأَتَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا نَبِيَّ اللَّهِ خَطَبَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏ابْنَتِي فَأَنْكَحَهَا أَبُوهَا يَتِيمًا فِي حَجْرِهِ وَلَمْ يُؤَامِرْهَا فَأَرْسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏صَالِحٍ ‏ ‏فَقَالَ أَنْكَحْتَ ابْنَتَكَ وَلَمْ تُؤَامِرْهَا فَقَالَ نَعَمْ فَقَالَ ‏ ‏أَشِيرُوا عَلَى النِّسَاءِ فِي أَنْفُسِهِنَّ وَهِيَ ‏ ‏بِكْرٌ ‏ ‏فَقَالَ ‏ ‏صَالِحٌ ‏ ‏فَإِنَّمَا فَعَلْتُ هَذَا لِمَا ‏ ‏يُصْدِقُهَا ‏ ‏ابْنُ عُمَرَ ‏ ‏فَإِنَّ لَهُ فِي مَالِي مِثْلَ مَا أَعْطَاهَا ‏","","",""],[5463,5463,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُثْمَانَ الْوَلِيدُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ ‏ ‏أَبَرَّ ‏ ‏الْبِرِّ أَنْ يَصِلَ الرَّجُلُ أَهْلَ وُدِّ أَبِيهِ ‏","","",""],[5464,5464,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَخْبَرَنَا ‏ ‏عَوْنُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏كُنَّا جُلُوسًا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَجُلٌ اللَّهُ أَكْبَرُ كَبِيرًا وَالْحَمْدُ لِلَّهِ كَثِيرًا وَسُبْحَانَ اللَّهِ ‏ ‏بُكْرَةً ‏ ‏وَأَصِيلًا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ الْكَلِمَاتِ فَقَالَ الرَّجُلُ أَنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏إِنِّي لَأَنْظُرُ إِلَيْهَا تَصْعَدُ حَتَّى فُتِحَتْ لَهَا أَبْوَابُ السَّمَاءِ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ مَا تَرَكْتُهَا مُنْذُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و قَالَ ‏ ‏عَوْنٌ ‏ ‏مَا تَرَكْتُهَا مُنْذُ سَمِعْتُهَا مِنْ ‏ ‏ابْنِ عُمَرَ ‏","","",""],[5465,5465,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُحِلَّتْ لَنَا مَيْتَتَانِ وَدَمَانِ فَأَمَّا الْمَيْتَتَانِ فَالْحُوتُ وَالْجَرَادُ وَأَمَّا الدَّمَانِ فَالْكَبِدُ وَالطِّحَالُ ‏","","",""],[5466,5466,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي الزَّاهِرِيَّةِ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَقِيمُوا الصُّفُوفَ فَإِنَّمَا تَصُفُّونَ بِصُفُوفِ الْمَلَائِكَةِ ‏ ‏وَحَاذُوا ‏ ‏بَيْنَ ‏ ‏الْمَنَاكِبِ ‏ ‏وَسُدُّوا الْخَلَلَ وَلِينُوا فِي أَيْدِي إِخْوَانِكُمْ وَلَا تَذَرُوا فُرُجَاتٍ لِلشَّيْطَانِ وَمَنْ وَصَلَ صَفًّا وَصَلَهُ اللَّهُ تَبَارَكَ وَتَعَالَى وَمَنْ قَطَعَ صَفًّا قَطَعَهُ اللَّهُ ‏","","",""],[5467,5467,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏وَإِبْرَاهِيمُ بْنُ الْمُهَاجِرِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ائْذَنُوا لِلنِّسَاءِ بِاللَّيْلِ إِلَى الْمَسَاجِدِ ‏ ‏تَفِلَاتٍ ‏ ‏لَيْثٌ ‏ ‏الَّذِي ذَكَرَ ‏ ‏تَفِلَاتٍ ‏","","",""],[5468,5468,"","","‏ ‏حَدَّثَنَا ‏ ‏أَزْهَرُ بنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَخْطُبُ خُطْبَتَيْنِ يَوْمَ الْجُمُعَةِ يَجْلِسُ بَيْنَهُمَا مَرَّةً ‏","","",""],[5469,5469,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏كَسَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُبْطِيَّةً ‏ ‏وَكَسَا ‏ ‏أُسَامَةَ ‏ ‏حُلَّةً ‏ ‏سِيَرَاءَ ‏ ‏قَالَ فَنَظَرَ فَرَآنِي قَدْ ‏ ‏أَسْبَلْتُ ‏ ‏فَجَاءَ فَأَخَذَ بِمَنْكِبِي وَقَالَ يَا ‏ ‏ابْنَ عُمَرَ ‏ ‏كُلُّ شَيْءٍ مَسَّ الْأَرْضَ مِنْ الثِّيَابِ فَفِي النَّارِ ‏ ‏قَالَ ‏ ‏فَرَأَيْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَتَّزِرُ إِلَى نِصْفِ السَّاقِ ‏","","",""],[5470,5470,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَهُوَ يَخْطُبُ ‏ ‏الْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى الْيَدُ الْعُلْيَا الْمُعْطِيَةُ وَالْيَدُ السُّفْلَى يَدُ السَّائِلِ ‏","","",""],[5471,5471,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّي ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الَّذِي لَا يُؤَدِّي زَكَاةَ مَالِهِ ‏ ‏يُمَثِّلُ ‏ ‏اللَّهُ عَزَّ وَجَلَّ لَهُ مَالَهُ يَوْمَ الْقِيَامَةِ شُجَاعًا أَقْرَعَ لَهُ ‏ ‏زَبِيبَتَانِ ‏ ‏ثُمَّ يَلْزَمُهُ يُطَوِّقُهُ يَقُولُ أَنَا كَنْزُكَ أَنَا كَنْزُكَ ‏","","",""],[5472,5472,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَفَعَ الْحَدِيثَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ مُسْكِرٍ خَمْرٌ وَكُلُّ مُسْكِرٍ حَرَامٌ وَمَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا فَمَاتَ وَهُوَ مُدْمِنُهَا لَمْ يَتُبْ لَمْ يَشْرَبْهَا فِي الْآخِرَةِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَفِي مَوْضِعٍ آخَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مُسْكِرٍ خَمْرٌ وَكُلُّ مُسْكِرٍ حَرَامٌ ‏","","",""],[5473,5473,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ الْحِمْصِيُّ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ زُفَرَ ‏ ‏عَنْ ‏ ‏هَاشِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَنْ اشْتَرَى ثَوْبًا بِعَشَرَةِ دَرَاهِمَ وَفِيهِ دِرْهَمٌ حَرَامٌ لَمْ يَقْبَلْ اللَّهُ لَهُ صَلَاةً مَادَامَ عَلَيْهِ ‏ ‏قَالَ ‏ ‏ثُمَّ أَدْخَلَ أُصْبُعَيْهِ فِي أُذُنَيْهِ ثُمَّ قَالَ صُمَّتَا إِنْ لَمْ يَكُنْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعْتُهُ يَقُولُهُ ‏","","",""],[5474,5474,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْبَهِيِّ ‏ ‏قَالَ ‏ ‏شَرِيكٌ ‏ ‏أُرَاهُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى ‏ ‏الْخُمْرَةِ ‏","","",""],[5475,5475,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏هُرَيْمٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏تُحْمَلُ مَعَهُ ‏ ‏الْعَنَزَةُ ‏ ‏فِي الْعِيدَيْنِ فِي أَسْفَارِهِ فَتُرْكَزُ بَيْنَ يَدَيْهِ فَيُصَلِّي إِلَيْهَا ‏","","",""],[5476,5476,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏زَيْدٍ الْعَمِّيِّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَوَضَّأَ وَاحِدَةً فَتِلْكَ وَظِيفَةُ الْوُضُوءِ الَّتِي لَا بُدَّ مِنْهَا وَمَنْ تَوَضَّأَ اثْنَتَيْنِ فَلَهُ ‏ ‏كِفْلَانِ ‏ ‏وَمَنْ تَوَضَّأَ ثَلَاثًا فَذَلِكَ وُضُوئِي وَوُضُوءُ الْأَنْبِيَاءِ قَبْلِي ‏","","",""],[5477,5477,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ قُدَامَةَ بْنِ إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ حَاطِبٍ الْجُمَحِيُّ أَبُو مُحَمَّدٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ حَالِفًا فَلَا يَحْلِفْ إِلَّا بِاللَّهِ وَكَانَتْ ‏ ‏قُرَيْشٌ ‏ ‏تَحْلِفُ بِآبَائِهَا قَالَ فَلَا تَحْلِفُوا بِآبَائِكُمْ ‏","","",""],[5478,5478,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا طَافَ الطَّوَافَ الْأَوَّلَ ‏ ‏خَبَّ ‏ ‏ثَلَاثًا وَمَشَى أَرْبَعًا وَكَانَ ‏ ‏يَسْعَى ‏ ‏بِبَطْنِ الْمَسِيلِ ‏ ‏إِذَا طَافَ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏","","",""],[5479,5479,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَخْرُجُ نَارٌ مِنْ قِبَلِ ‏ ‏حَضْرَمَوْتَ ‏ ‏تَحْشُرُ النَّاسَ قَالَ قُلْنَا فَمَا تَأْمُرُنَا يَا رَسُولَ اللَّهِ قَالَ عَلَيْكُمْ ‏ ‏بِالشَّأْمِ ‏","","",""],[5480,5480,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ سَلْمَانَ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏حَفِظْتُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشْرَ صَلَوَاتٍ ‏ ‏رَكْعَتَيْنِ قَبْلَ صَلَاةِ الصُّبْحِ وَرَكْعَتَيْنِ قَبْلَ صَلَاةِ الظُّهْرِ وَرَكْعَتَيْنِ بَعْدَ صَلَاةِ الظُّهْرِ وَرَكْعَتَيْنِ بَعْدَ صَلَاةِ الْمَغْرِبِ وَرَكْعَتَيْنِ بَعْدَ الْعِشَاءِ ‏","","",""],[5481,5481,"","","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَخَذَ شَيْئًا مِنْ الْأَرْضِ ظُلْمًا خُسِفَ بِهِ إِلَى سَبْعِ أَرَضِينَ ‏","","",""],[5482,5482,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ حُنَيْنٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَهَبَ مَذْهَبًا مُوَاجِهًا لِلْقِبْلَةِ ‏","","",""],[5483,5483,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَمَقْتُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعًا وَعِشْرِينَ ‏ ‏أَوْ خَمْسًا وَعِشْرِينَ ‏ ‏مَرَّةً ‏ ‏يَقْرَأُ فِي الرَّكْعَتَيْنِ قَبْلَ الْفَجْرِ وَالرَّكْعَتَيْنِ بَعْدَ الْمَغْرِبِ بْ ‏ ‏قُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏وَقُلْ هُوَ اللَّهُ أَحَدٌ ‏","","",""],[5484,5484,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سَأَلَكُمْ بِاللَّهِ فَأَعْطُوهُ وَمَنْ اسْتَعَاذَكُمْ بِاللَّهِ فَأَعِيذُوهُ وَمَنْ أَتَى إِلَيْكُمْ مَعْرُوفًا فَكَافِئُوهُ فَإِنْ لَمْ تَجِدُوا مَا تُكَافِئُوهُ فَادْعُوا لَهُ حَتَّى تَعْلَمُوا أَنَّكُمْ قَدْ كَافَأْتُمُوهُ وَمَنْ اسْتَجَارَكُمْ فَأَجِيرُوهُ ‏","","",""],[5485,5485,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا ‏ ‏فِئَةُ ‏ ‏كُلِّ مُسْلِمٍ ‏","","",""],[5486,5486,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ أَبِي سُلَيْمٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فَلَا ‏ ‏يَتَنَخَّمَنَّ ‏ ‏تُجَاهَ الْقِبْلَةِ فَإِنَّ تُجَاهَهُ الرَّحْمَنُ وَلَا عَنْ يَمِينِهِ وَلَكِنْ عَنْ شِمَالِهِ أَوْ تَحْتَ قَدَمِهِ الْيُسْرَى ‏","","",""],[5487,5487,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ حَاتِمِ بْنِ مُسْلِمٍ ‏ ‏سَمِعْتُ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ امْرَأَةً جَاءَتْ إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏بِمِنًى ‏ ‏عَلَيْهَا ‏ ‏دِرْعُ ‏ ‏حَرِيرٍ فَقَالَتْ مَا تَقُولُ فِي الْحَرِيرِ فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْهُ ‏","","",""],[5488,5488,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ يَعْنِي ابْنَ عُتْبَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَخَلَّى ‏ ‏عَلَى ‏ ‏لَبِنَتَيْنِ ‏ ‏مُسْتَقْبِلَ الْقِبْلَةِ ‏","","",""],[5489,5489,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏حَدَّثَهُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُعْطِي ‏ ‏عُمَرَ ‏ ‏الْعَطَاءَ فَيَقُولُ لَهُ ‏ ‏عُمَرُ ‏ ‏أَعْطِهِ يَا رَسُولَ اللَّهِ أَفْقَرَ إِلَيْهِ مِنِّي فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُذْهُ فَتَمَوَّلْهُ أَوْ ‏ ‏تَصَدَّقْ ‏ ‏بِهِ وَمَا جَاءَكَ مِنْ هَذَا الْمَالِ وَأَنْتَ غَيْرُ ‏ ‏مُشْرِفٍ ‏ ‏وَلَا سَائِلٍ فَخُذْهُ وَمَالَا فَلَا تُتْبِعْهُ نَفْسَكَ ‏ ‏قَالَ ‏ ‏سَالِمٌ ‏ ‏فَمِنْ أَجْلِ ذَلِكَ كَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لَا يَسْأَلُ أَحَدًا شَيْئًا وَلَا يَرُدُّ شَيْئًا ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنِ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏حُوَيْطِبِ بْنِ عَبْدِ الْعُزَّى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ السَّعْدِيِّ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[5490,5490,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَارِثِ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ حَرْبٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ قُلْتُ مَا تَقُولُ فِي الصَّوْمِ فِي السَّفَرِ قَالَ تَأْخُذُ إِنْ حَدَّثْتُكَ قُلْتُ نَعَمْ قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَرَجَ مِنْ هَذِهِ ‏ ‏الْمَدِينَةِ ‏ ‏قَصَرَ الصَّلَاةَ وَلَمْ يَصُمْ حَتَّى يَرْجِعَ إِلَيْهَا ‏","","",""],[5491,5491,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ عَطَاءٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏حَدَّثَنِي ‏ ‏الْحَسَنُ بْنُ سُهَيْلِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمِيثَرَةِ ‏ ‏وَالْقَسِّيَّةِ ‏ ‏وَحَلْقَةِ الذَّهَبِ ‏ ‏وَالْمُفْدَمِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏وَالْمِيثَرَةُ ‏ ‏جُلُودُ ‏ ‏السِّبَاعِ ‏ ‏وَالْقَسِّيَّةُ ثِيَابٌ مُضَلَّعَةٌ مِنْ ‏ ‏إِبْرَيْسَمٍ ‏ ‏يُجَاءُ بِهَا مِنْ ‏ ‏مِصْرَ ‏ ‏وَالْمُفْدَمُ ‏ ‏الْمُشَبَّعُ بِالْعُصْفُرِ ‏","","",""],[5492,5492,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ يَعْنِي الطَّحَّانَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَقِينَا الْعَدُوَّ ‏ ‏فَحَاصَ ‏ ‏الْمُسْلِمُونَ ‏ ‏حَيْصَةً ‏ ‏فَكُنْتُ فِيمَنْ ‏ ‏حَاصَ ‏ ‏فَدَخَلْنَا ‏ ‏الْمَدِينَةَ ‏ ‏قَالَ فَتَعَرَّضْنَا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ خَرَجَ لِلصَّلَاةِ فَقُلْنَا يَا رَسُولَ اللَّهِ نَحْنُ ‏ ‏الْفَرَّارُونَ ‏ ‏قَالَ ‏ ‏لَا بَلْ أَنْتُمْ ‏ ‏الْعَكَّارُونَ ‏ ‏إِنِّي ‏ ‏فِئَةٌ ‏ ‏لَكُمْ ‏","","",""],[5493,5493,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ قَرْمٍ ‏ ‏عَنْ ‏ ‏زَيْدٍ يَعْنِي ابْنَ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزَاةٍ غَزَاهَا بِامْرَأَةٍ مَقْتُولَةٍ ‏ ‏فَنَهَى عَنْ قَتْلِ النِّسَاءِ وَالصِّبْيَانِ ‏","","",""],[5494,5494,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَوْنِ بْنِ أَبِي جُحَيْفَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سُمَيْرَةَ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏رَأَى رَأْسًا فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَمْنَعُ أَحَدَكُمْ إِذَا جَاءَهُ مَنْ يُرِيدُ قَتْلَهُ أَنْ يَكُونَ مِثْلَ ابْنِ ‏ ‏آدَمَ ‏ ‏الْقَاتِلُ فِي النَّارِ وَالْمَقْتُولُ فِي الْجَنَّةِ ‏","","",""],[5495,5495,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَحِيرٍ الصَّنْعَانِيُّ الْقَاصُّ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ يَزِيدَ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى يَوْمِ الْقِيَامَةِ كَأَنَّهُ رَأْيُ عَيْنٍ فَلْيَقْرَأْ ‏ ‏إِذَا الشَّمْسُ ‏ ‏كُوِّرَتْ ‏ ‏وَإِذَا السَّمَاءُ انْفَطَرَتْ ‏ ‏وَحَسِبْتُ أَنَّهُ قَالَ وَسُورَةَ ‏ ‏هُودٍ ‏","","",""],[5496,5496,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَأَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ وَالْعَصْرَ وَالْمَغْرِبَ وَالْعِشَاءَ ‏ ‏بِالْبَطْحَاءِ ‏ ‏ثُمَّ ‏ ‏هَجَعَ ‏ ‏بِهَا ‏ ‏هَجْعَةً ‏ ‏ثُمَّ دَخَلَ ‏ ‏مَكَّةَ ‏ ‏فَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَفْعَلُهُ ‏","","",""],[5497,5497,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏مَطَرٌ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَافَرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَ ‏ ‏عُمَرَ ‏ ‏فَلَمْ أَرَهُمَا يَزِيدَانِ عَلَى رَكْعَتَيْنِ وَكُنَّا ضُلَّالًا فَهَدَانَا اللَّهُ بِهِ فَبِهِ نَقْتَدِي ‏","","",""],[5498,5498,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏سَمِعْتُ ‏ ‏الْمُغِيرَةَ بْنَ سَلْمَانَ ‏ ‏يُحَدِّثُ ‏ ‏فِي بَيْتِ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏حَفِظْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشْرَ رَكَعَاتٍ سِوَى الْفَرِيضَةِ ‏ ‏رَكْعَتَيْنِ قَبْلَ الظُّهْرِ وَرَكْعَتَيْنِ بَعْدَ الظُّهْرِ وَرَكْعَتَيْنِ بَعْدَ الْمَغْرِبِ وَرَكْعَتَيْنِ بَعْدَ الْعِشَاءِ وَرَكْعَتَيْنِ قَبْلَ ‏ ‏الْغَدَاةِ ‏","","",""],[5499,5499,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ الْعُقَيْلِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا مِنْ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَلَاةِ اللَّيْلِ فَقَالَ بِإِصْبَعَيْهِ مَثْنَى مَثْنَى ‏ ‏وَالْوَتْرُ ‏ ‏رَكْعَةٌ مِنْ آخِرِ اللَّيْلِ ‏","","",""],[5500,5500,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمُ بْنُ أَخْضَرَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏يَرْمُلُ ‏ ‏مِنْ الْحَجَرِ إِلَى الْحَجَرِ وَيُخْبِرُنَا أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُ ذَلِكَ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏فَذَكَرُوا ‏ ‏لِنَافِعٍ ‏ ‏أَنَّهُ كَانَ يَمْشِي مَا بَيْنَ الرُّكْنَيْنِ قَالَ ‏ ‏مَا كَانَ يَمْشِي إِلَّا حِينَ يُرِيدُ أَنْ يَسْتَلِمَ ‏","","",""],[5501,5501,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏سَمِعْتُ ‏ ‏نَافِعًا ‏ ‏يَزْعُمُ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏سَاوَمَتْ ‏ ‏بِبَرِيرَةَ ‏ ‏فَخَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الصَّلَاةِ فَلَمَّا رَجَعَ قَالَتْ إِنَّهُمْ أَبَوْا أَنْ يَبِيعُونِي إِلَّا أَنْ يَشْتَرِطُوا ‏ ‏الْوَلَاءَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْتَقَ ‏","","",""],[5502,5502,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا دَخَلَ الصَّلَاةَ رَفَعَ يَدَيْهِ ‏ ‏حَذْوَ ‏ ‏مَنْكِبَيْهِ ‏ ‏وَإِذَا رَكَعَ وَإِذَا رَفَعَ مِنْ الرُّكُوعِ ‏","","",""],[5503,5503,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو مَطَرٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَمِعَ الرَّعْدَ وَالصَّوَاعِقَ قَالَ ‏ ‏اللَّهُمَّ لَا تَقْتُلْنَا بِغَضَبِكَ وَلَا تُهْلِكْنَا بِعَذَابِكَ ‏ ‏وَعَافِنَا قَبْلَ ذَلِكَ ‏","","",""],[5504,5504,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْجَرِّ ‏ ‏وَالدُّبَّاءِ ‏","","",""],[5505,5505,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ فِي أَوَّلِ أَمْرِهِ ‏ ‏إِنَّهَا لَا تَنْفِرُ ‏ ‏قَالَ ثُمَّ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏رَخَّصَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَهُنَّ ‏","","",""],[5506,5506,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا دُعِيَ أَحَدُكُمْ إِلَى الدَّعْوَةِ فَلْيُجِبْ ‏ ‏أَوْ قَالَ فَلْيَأْتِهَا ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يُجِيبُ صَائِمًا وَمُفْطِرًا ‏","","",""],[5507,5507,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَصْحَابَ هَذِهِ الصُّوَرِ يُعَذَّبُونَ يَوْمَ الْقِيَامَةِ وَيُقَالُ لَهُمْ أَحْيُوا مَا خَلَقْتُمْ ‏","","",""],[5508,5508,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏فِي ‏ ‏نَوَاصِيهَا ‏ ‏الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[5509,5509,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْقَزَعِ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏تَفْسِيرُهُ أَنْ يُحْلَقَ بَعْضُ رَأْسِ الصَّبِيِّ وَيُتْرَكَ مِنْهُ ‏ ‏ذُؤَابَةٌ ‏","","",""],[5510,5510,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏كُنَّا إِذَا ‏ ‏بَايَعْنَا ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى السَّمْعِ وَالطَّاعَةِ يُلَقِّنُنَا هُوَ فِيمَا اسْتَطَعْتَ ‏","","",""],[5511,5511,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ مِنْ ‏ ‏مِصْرَ ‏ ‏يَحُجُّ ‏ ‏الْبَيْتَ ‏ ‏قَالَ فَرَأَى قَوْمًا جُلُوسًا فَقَالَ مَنْ هَؤُلَاءِ الْقَوْمُ فَقَالُوا ‏ ‏قُرَيْشٌ ‏ ‏قَالَ فَمَنْ الشَّيْخُ فِيهِمْ قَالُوا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏قَالَ يَا ‏ ‏ابْنَ عُمَرَ ‏ ‏إِنِّي سَائِلُكَ عَنْ شَيْءٍ ‏ ‏أَوْ ‏ ‏أَنْشُدُكَ ‏ ‏أَوْ ‏ ‏نَشَدْتُكَ ‏ ‏بِحُرْمَةِ هَذَا ‏ ‏الْبَيْتِ ‏ ‏أَتَعْلَمُ أَنَّ ‏ ‏عُثْمَانَ ‏ ‏فَرَّ ‏ ‏يَوْمَ ‏ ‏أُحُدٍ ‏ ‏قَالَ نَعَمْ قَالَ فَتَعْلَمُ أَنَّهُ غَابَ عَنْ ‏ ‏بَدْرٍ ‏ ‏فَلَمْ يَشْهَدْهُ قَالَ نَعَمْ قَالَ وَتَعْلَمُ أَنَّهُ تَغَيَّبَ عَنْ ‏ ‏بَيْعَةِ ‏ ‏الرِّضْوَانِ قَالَ نَعَمْ قَالَ فَكَبَّرَ الْمِصْرِيُّ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏تَعَالَ أُبَيِّنْ لَكَ مَا سَأَلْتَنِي عَنْهُ أَمَّا فِرَارُهُ يَوْمَ ‏ ‏أُحُدٍ ‏ ‏فَأَشْهَدُ أَنَّ اللَّهَ قَدْ عَفَا عَنْهُ وَغَفَرَ لَهُ وَأَمَّا تَغَيُّبُهُ عَنْ ‏ ‏بَدْرٍ ‏ ‏فَإِنَّهُ كَانَتْ تَحْتَهُ ابْنَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّهَا مَرِضَتْ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَكَ أَجْرُ رَجُلٍ شَهِدَ ‏ ‏بَدْرًا ‏ ‏وَسَهْمُهُ ‏ ‏وَأَمَّا تَغَيُّبُهُ عَنْ ‏ ‏بَيْعَةِ ‏ ‏الرِّضْوَانِ فَلَوْ كَانَ أَحَدٌ أَعَزَّ بِبَطْنِ ‏ ‏مَكَّةَ ‏ ‏مِنْ ‏ ‏عُثْمَانَ ‏ ‏لَبَعَثَهُ بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُثْمَانَ ‏ ‏وَكَانَتْ ‏ ‏بَيْعَةُ ‏ ‏الرِّضْوَانِ بَعْدَمَا ذَهَبَ ‏ ‏عُثْمَانُ ‏ ‏فَضَرَبَ بِهَا يَدَهُ عَلَى يَدِهِ وَقَالَ هَذِهِ ‏ ‏لِعُثْمَانَ ‏ ‏قَالَ وَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏اذْهَبْ بِهَذَا الْآنَ مَعَكَ ‏","","",""],[5512,5512,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آشْتَرِي الذَّهَبَ بِالْفِضَّةِ أَوْ الْفِضَّةَ بِالذَّهَبِ قَالَ ‏ ‏إِذَا أَخَذْتَ وَاحِدًا مِنْهُمَا بِالْآخَرِ فَلَا يُفَارِقْكَ صَاحِبُكَ وَبَيْنَكَ وَبَيْنَهُ ‏ ‏لَبْسٌ ‏","","",""],[5513,5513,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَأْتِي ‏ ‏قُبَاءَ ‏ ‏رَاكِبًا وَمَاشِيًا ‏","","",""],[5514,5514,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏اقْتَنَى ‏ ‏كَلْبًا إِلَّا كَلْبَ مَاشِيَةٍ أَوْ كَلْبَ صَيْدٍ نَقَصَ مِنْ عَمَلِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطَانِ ‏ ‏وَكَانَ يَأْمُرُ بِالْكِلَابِ أَنْ تُقْتَلَ ‏","","",""],[5515,5515,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الَّذِي يَجُرُّ ثَوْبَهُ مِنْ ‏ ‏الْخُيَلَاءِ ‏ ‏لَا يَنْظُرُ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[5516,5516,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَتَى الْجُمُعَةَ فَلْيَغْتَسِلْ ‏","","",""],[5517,5517,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِي غَيْرِهِ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏","","",""],[5518,5518,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةُ الْجَمَاعَةِ تَفْضُلُ صَلَاةَ أَحَدِكُمْ بِسَبْعٍ وَعِشْرِينَ دَرَجَةً ‏","","",""],[5519,5519,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ فَاتَتْهُ صَلَاةُ الْعَصْرِ فَكَأَنَّمَا ‏ ‏وُتِرَ ‏ ‏أَهْلَهُ وَمَالَهُ ‏","","",""],[5520,5520,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَضَ زَكَاةَ الْفِطْرِ صَاعًا مِنْ تَمْرٍ أَوْ صَاعًا مِنْ شَعِيرٍ عَلَى كُلِّ عَبْدٍ أَوْ حُرٍّ صَغِيرٍ أَوْ كَبِيرٍ ‏","","",""],[5521,5521,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ أَيَرْقُدُ أَحَدُنَا وَهُوَ ‏ ‏جُنُبٌ ‏ ‏قَالَ ‏ ‏نَعَمْ إِذَا تَوَضَّأَ ‏","","",""],[5522,5522,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْخَيْلُ فِي ‏ ‏نَوَاصِيهَا ‏ ‏الْخَيْرُ أَبَدًا إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[5523,5523,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا نَصَحَ الْعَبْدُ لِسَيِّدِهِ وَأَحْسَنَ عِبَادَةَ رَبِّهِ كَانَ لَهُ مِنْ الْأَجْرِ مَرَّتَيْنِ ‏","","",""],[5524,5524,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُقِيمُ الرَّجُلُ الرَّجُلَ مِنْ مَجْلِسِهِ ثُمَّ يَجْلِسُ فِيهِ وَلَكِنْ تَفَسَّحُوا وَتَوَسَّعُوا ‏","","",""],[5525,5525,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ أَكْلِ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏وَسَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[5526,5526,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اشْتَرَى نَخْلًا قَدْ ‏ ‏أُبِّرَتْ ‏ ‏فَثَمَرَتُهَا لِلَّذِي ‏ ‏أَبَّرَهَا ‏ ‏إِلَّا أَنْ يَشْرِطَ الَّذِي اشْتَرَاهَا ‏","","",""],[5527,5527,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسَ ذَاتَ يَوْمٍ فَجِئْتُ وَقَدْ فَرَغَ فَسَأَلْتُ النَّاسَ مَاذَا قَالَ قَالُوا ‏ ‏نَهَى أَنْ ‏ ‏يُنْتَبَذَ ‏ ‏فِي ‏ ‏الْمُزَفَّتِ ‏ ‏وَالْقَرْعِ ‏","","",""],[5528,5528,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّمَا ‏ ‏مَثَلُ الْمُنَافِقِ مَثَلُ الشَّاةِ ‏ ‏الْعَائِرَةِ ‏ ‏بَيْنَ الْغَنَمَيْنِ ‏ ‏تَعِيرُ ‏ ‏إِلَى هَذِهِ مَرَّةً وَإِلَى هَذِهِ مَرَّةً لَا تَدْرِي أَيَّهُمَا تَتْبَعُ ‏","","",""],[5529,5529,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَدَّ بِهِ السَّيْرُ جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏","","",""],[5530,5530,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏طَلَّقْتُ امْرَأَتِي عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِيَ حَائِضٌ فَذَكَرَ ذَلِكَ ‏ ‏عُمَرُ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مُرْهُ فَلْيُرَاجِعْهَا حَتَّى تَطْهُرَ ثُمَّ تَحِيضَ أُخْرَى فَإِذَا طَهُرَتْ يُطَلِّقُهَا إِنْ شَاءَ قَبْلَ أَنْ يُجَامِعَهَا أَوْ ‏ ‏يُمْسِكَهَا ‏ ‏فَإِنَّهَا ‏ ‏الْعِدَّةُ ‏ ‏الَّتِي أَمَرَ اللَّهُ أَنْ تُطَلَّقَ لَهَا النِّسَاءُ ‏","","",""],[5531,5531,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَلَى الْمِنْبَرِ عَنْ صَلَاةِ اللَّيْلِ قَالَ مَثْنَى مَثْنَى فَإِذَا خَشِيَ أَحَدُكُمْ أَنْ يُصْبِحَ صَلَّى وَاحِدَةً ‏ ‏فَأَوْتَرَتْ ‏ ‏لَهُ مَا صَلَّى ‏","","",""],[5532,5532,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اجْعَلُوا آخِرَ صَلَاتِكُمْ بِاللَّيْلِ ‏ ‏وِتْرًا ‏","","",""],[5533,5533,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاصَلَ ‏ ‏فِي رَمَضَانَ ‏ ‏فَوَاصَلَ ‏ ‏النَّاسُ فَنَهَاهُمْ فَقِيلَ لَهُ إِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏قَالَ ‏ ‏إِنِّي لَسْتُ مِثْلَكُمْ إِنِّي أُطْعَمُ وَأُسْقَى ‏","","",""],[5534,5534,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏حَمَلَ عَلَى فَرَسٍ فِي سَبِيلِ اللَّهِ فَأَعْطَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا فَجَاءَ ‏ ‏عُمَرُ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَبْتَاعُ ‏ ‏الْفَرَسَ الَّذِي حَمَلْتُ عَلَيْهِ فَقَالَ ‏ ‏لَا ‏ ‏تَبْتَعْهُ ‏ ‏وَلَا تَرْجِعْ فِي ‏ ‏صَدَقَتِكَ ‏","","",""],[5535,5535,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَأَى ‏ ‏حُلَّةً ‏ ‏سِيَرَاءَ ‏ ‏تُبَاعُ عِنْدَ بَابِ الْمَسْجِدِ فَقَالَ يَا رَسُولَ اللَّهِ لَوْ اشْتَرَيْتَهَا فَلَبِسْتَهَا يَوْمَ الْجُمُعَةِ وَلِلْوُفُودِ إِذَا قَدِمُوا عَلَيْكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا يَلْبَسُ هَذِهِ مَنْ لَا خَلَاقَ لَهُ فِي الْآخِرَةِ ثُمَّ جَاءَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهَا ‏ ‏حُلَلٌ ‏ ‏فَأَعْطَى ‏ ‏عُمَرَ ‏ ‏مِنْهَا ‏ ‏حُلَّةً ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ كَسَوْتَنِيهَا وَقَدْ قُلْتَ فِيهَا مَا قُلْتَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَمْ أَكْسُكَهَا لَتَلْبَسَهَا إِنَّمَا كَسَوْتُكَهَا لِتَبِيعَهَا أَوْ لِتَكْسُوَهَا قَالَ فَكَسَاهَا ‏ ‏عُمَرُ ‏ ‏أَخًا لَهُ ‏ ‏مُشْرِكًا مِنْ أُمِّهِ ‏ ‏بِمَكَّةَ ‏","","",""],[5536,5536,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي يَكْذِبُ عَلَيَّ ‏ ‏يُبْنَى لَهُ بَيْتٌ فِي النَّارِ ‏","","",""],[5537,5537,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ الرِّجَالَ وَالنِّسَاءَ كَانُوا ‏ ‏يَتَوَضَّئُونَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْإِنَاءِ الْوَاحِدِ جَمِيعًا ‏","","",""],[5538,5538,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏نَادَى بِالصَّلَاةِ فِي لَيْلَةٍ ذَاتِ بَرْدٍ وَرِيحٍ ثُمَّ قَالَ فِي آخِرِ نِدَائِهِ أَلَا صَلُّوا فِي ‏ ‏رِحَالِكُمْ ‏ ‏أَلَا صَلُّوا فِي ‏ ‏رِحَالِكُمْ ‏ ‏أَلَا صَلُّوا فِي ‏ ‏الرِّحَالِ ‏ ‏فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَأْمُرُ الْمُؤَذِّنَ إِذَا كَانَتْ لَيْلَةٌ بَارِدَةٌ أَوْ ذَاتُ مَطَرٍ أَوْ ذَاتُ رِيحٍ فِي السَّفَرِ أَلَا صَلُّوا فِي ‏ ‏الرِّحَالِ ‏","","",""],[5539,5539,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏الْمِنْهَالُ بْنُ عَمْرٍو ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فِي طَرِيقٍ مِنْ طُرُقِ ‏ ‏الْمَدِينَةِ ‏ ‏فَرَأَى فِتْيَانًا قَدْ نَصَبُوا دَجَاجَةً يَرْمُونَهَا لَهُمْ كُلُّ خَاطِئَةٍ فَقَالَ مَنْ فَعَلَ هَذَا وَغَضِبَ فَلَمَّا رَأَوْا ‏ ‏ابْنَ عُمَرَ ‏ ‏تَفَرَّقُوا ثُمَّ قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ اللَّهُ مَنْ ‏ ‏يُمَثِّلُ ‏ ‏بِالْحَيَوَانِ ‏","","",""],[5540,5540,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏جَبَلَةُ ‏ ‏أَخْبَرَنِي قَالَ ‏ ‏كُنَّا ‏ ‏بِالْمَدِينَةِ ‏ ‏فِي ‏ ‏بَعْثِ ‏ ‏الْعِرَاقِ ‏ ‏فَكَانَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏يَرْزُقُنَا التَّمْرَ وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَمُرُّ بِنَا فَيَقُولُ لَا تُقَارِنُوا فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْقِرَانِ ‏ ‏إِلَّا أَنْ يَسْتَأْذِنَ الرَّجُلُ مِنْكُمْ أَخَاهُ ‏","","",""],[5541,5541,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏جَبَلَةُ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ جَرَّ ثَوْبًا مِنْ ثِيَابِهِ مِنْ ‏ ‏الْمَخِيلَةِ ‏ ‏فَإِنَّ اللَّهَ لَا يَنْظُرُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[5542,5542,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏الْغَادِرَ ‏ ‏يَنْصِبُ اللَّهُ لَهُ ‏ ‏لِوَاءً ‏ ‏يَوْمَ الْقِيَامَةِ فَيُقَالُ أَلَا هَذِهِ ‏ ‏غَدْرَةُ ‏ ‏فُلَانٍ ‏","","",""],[5543,5543,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ السَّدُوسِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ النَّاسَ يَوْمَ الْفَتْحِ فَقَالَ ‏ ‏أَلَا إِنَّ ‏ ‏دِيَةَ ‏ ‏الْخَطَإِ الْعَمْدِ بِالسَّوْطِ أَوْ الْعَصَا ‏ ‏مُغَلَّظَةٌ ‏ ‏مِائَةٌ مِنْ الْإِبِلِ مِنْهَا أَرْبَعُونَ ‏ ‏خَلِفَةً ‏ ‏فِي بُطُونِهَا أَوْلَادُهَا أَلَا إِنَّ كُلَّ دَمٍ وَمَالٍ ‏ ‏وَمَأْثُرَةٍ ‏ ‏كَانَتْ فِي الْجَاهِلِيَّةِ تَحْتَ قَدَمَيَّ إِلَّا مَا كَانَ مِنْ ‏ ‏سِقَايَةِ ‏ ‏الْحَاجِّ ‏ ‏وَسِدَانَةِ ‏ ‏الْبَيْتِ ‏ ‏فَإِنِّي قَدْ أَمْضَيْتُهَا ‏ ‏لِأَهْلِهَا ‏","","",""],[5544,5544,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وُضِعَ الْعَشَاءُ وَأُقِيمَتْ الصَّلَاةُ فَابْدَءُوا بِالْعَشَاءِ ‏ ‏قَالَ ‏ ‏وَلَقَدْ تَعَشَّى ‏ ‏ابْنُ عُمَرَ ‏ ‏مَرَّةً وَهُوَ يَسْمَعُ قِرَاءَةَ الْإِمَامِ ‏","","",""],[5545,5545,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏يَغْدُو ‏ ‏إِلَى الْمَسْجِدِ يَوْمَ الْجُمُعَةِ فَيُصَلِّي رَكَعَاتٍ يُطِيلُ فِيهِنَّ الْقِيَامَ فَإِذَا انْصَرَفَ الْإِمَامُ رَجَعَ إِلَى بَيْتِهِ فَصَلَّى رَكْعَتَيْنِ وَقَالَ هَكَذَا كَانَ يَفْعَلُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[5546,5546,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ إِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِيَادٌ يَعْنِي ابْنَ لَقِيطٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ نُعَيْمٍ الْأَعْرَجِيِّ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ ‏ ‏ابْنَ عُمَرَ ‏ ‏وَأَنَا عِنْدَهُ عَنْ ‏ ‏الْمُتْعَةِ ‏ ‏مُتْعَةِ ‏ ‏النِّسَاءِ ‏ ‏فَغَضِبَ وَقَالَ وَاللَّهِ مَا كُنَّا عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَنَّائِينَ وَلَا ‏ ‏مُسَافِحِينَ ‏ ‏ثُمَّ قَالَ وَاللَّهِ لَقَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيَكُونَنَّ قَبْلَ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏كَذَّابُونَ ثَلَاثُونَ أَوْ أَكْثَرُ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و قَالَ ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏قَبْلَ يَوْمِ الْقِيَامَةِ ‏","","",""],[5547,5547,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَاقِدِ بْنِ عَبْدِ اللَّهِ ‏ ‏كَذَا قَالَ ‏ ‏عَفَّانُ ‏ ‏وَإِنَّمَا هُوَ ‏ ‏وَاقِدُ بْنُ مُحَمَّدِ بْنِ زَيْدِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[5548,5548,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَاقِدِ بْنِ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي حَجَّةِ الْوَدَاعِ ‏ ‏وَيْحَكُمْ أَوْ قَالَ ‏ ‏وَيْلَكُمْ لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[5549,5549,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏قُدَامَةُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ حُصَيْنٍ التَّمِيمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عَلْقَمَةَ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏يَسَارٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَآنِي ‏ ‏ابْنُ عُمَرَ ‏ ‏وَأَنَا أُصَلِّي بَعْدَمَا طَلَعَ الْفَجْرُ فَقَالَ يَا ‏ ‏يَسَارُ ‏ ‏كَمْ صَلَّيْتَ قُلْتُ لَا أَدْرِي قَالَ لَا دَرَيْتَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ عَلَيْنَا وَنَحْنُ نُصَلِّ هَذِهِ الصَّلَاةَ فَقَالَ ‏ ‏أَلَا لِيُبَلِّغْ شَاهِدُكُمْ غَائِبَكُمْ أَنْ لَا صَلَاةَ بَعْدَ الصُّبْحِ إِلَّا سَجْدَتَانِ ‏","","",""],[5550,5550,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ الْغَلَابِيُّ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَدْعُو عَلَى أَرْبَعَةٍ فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏لَيْسَ لَكَ مِنْ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ ‏} ‏قَالَ وَهَدَاهُمْ اللَّهُ إِلَى الْإِسْلَامِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَبِيبِ بْنِ عَرَبِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدُ بْنُ الْحَارِثِ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[5551,5551,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ الْغَلَابِيُّ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَزَلَ ‏ ‏الْعَقِيقَ ‏ ‏فَنَهَى عَنْ ‏ ‏طُرُوقِ ‏ ‏النِّسَاءِ اللَّيْلَةَ الَّتِي يَأْتِي فِيهَا فَعَصَاهُ فَتَيَانِ فَكِلَاهُمَا رَأَى مَا كَرِهَ ‏","","",""],[5552,5552,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ وَهُوَ فِي ‏ ‏الْمُعَرَّسِ ‏ ‏مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏فِي ‏ ‏بَطْنِ الْوَادِي ‏ ‏فَقِيلَ إِنَّكَ فِي ‏ ‏بَطْحَاءَ ‏ ‏مُبَارَكَةٍ ‏","","",""],[5553,5553,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ جَرَّ ثَوْبَهُ ‏ ‏خُيَلَاءَ ‏ ‏لَمْ يَنْظُرْ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ أَحَدَ شِقَّيْ ‏ ‏إِزَارِي ‏ ‏لَيَسْتَرْخِي إِلَّا أَنْ أَتَعَاهَدَ ذَلِكَ مِنْهُ فَقَالَ إِنَّكَ لَسْتَ مِمَّنْ تَصْنَعُ ‏ ‏الْخُيَلَاءَ ‏","","",""],[5554,5554,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ رُؤْيَا رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّاسَ اجْتَمَعُوا فَقَامَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَنَزَعَ ذَنُوبًا أَوْ ذَنُوبَيْنِ وَفِي نَزْعِهِ ضَعْفٌ وَاللَّهُ يَغْفِرُ لَهُ ثُمَّ قَامَ ‏ ‏ابْنُ الْخَطَّابِ ‏ ‏فَاسْتَحَالَتْ ‏ ‏غَرْبًا ‏ ‏فَمَا رَأَيْتُ عَبْقَرِيًّا مِنْ النَّاسِ ‏ ‏يَفْرِي ‏ ‏فَرِيَّهُ ‏ ‏حَتَّى ضَرَبَ النَّاسُ بِعَطَنٍ ‏","","",""],[5555,5555,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اسْتَطَاعَ أَنْ يَمُوتَ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَلْيَمُتْ فَإِنِّي أَشْفَعُ لِمَنْ يَمُوتُ بِهَا ‏","","",""],[5556,5556,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنِي ‏ ‏يَعْلَى بْنُ حَكِيمٍ ‏ ‏سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏حَرَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَبِيذَ ‏ ‏الْجَرِّ ‏ ‏قَالَ ‏ ‏فَلَقِيتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَقُلْتُ ‏ ‏أَلَا تَعْجَبُ مِنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏يَزْعُمُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّمَ ‏ ‏نَبِيذَ ‏ ‏الْجَرِّ ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏صَدَقَ ‏ ‏فَقُلْتُ وَمَا ‏ ‏الْجَرُّ ‏ ‏قَالَ ‏ ‏مَا يُصْنَعُ مِنْ ‏ ‏الْمَدَرِ ‏","","",""],[5557,5557,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ مُسْكِرٍ خَمْرٌ وَكُلُّ مُسْكِرٍ حَرَامٌ ‏ ‏فَقُلْتُ لَهُ إِنَّ ‏ ‏أَصْحَابَنَا ‏ ‏حَدَّثُونَا عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَلَمْ يَرْفَعْهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَهُ ‏","","",""],[5558,5558,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏سَمِعْتُ ‏ ‏نَافِعًا ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَعْتَقَ نَصِيبًا لَهُ فِي عَبْدٍ فَإِنْ كَانَ لَهُ مِنْ الْمَالِ مَا يَبْلُغُ قِيمَتَهُ قُوِّمَ عَلَيْهِ قِيمَةَ ‏ ‏عَدْلٍ ‏ ‏وَإِلَّا فَقَدْ أَعْتَقَ مَا أَعْتَقَ ‏","","",""],[5559,5559,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏كَانَ ‏ ‏يُصَلِّي فِي اللَّيْلِ ‏ ‏وَيُوتِرُ ‏ ‏رَاكِبًا عَلَى بَعِيرِهِ لَا يُبَالِي حَيْثُ وَجَّهَهُ ‏ ‏قَالَ ‏ ‏وَقَدْ رَأَيْتُ أَنَا ‏ ‏سَالِمًا ‏ ‏يَصْنَعُ ذَلِكَ ‏ ‏وَقَدْ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَأْثُرُ ‏ ‏ذَلِكَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[5560,5560,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏صَخْرُ بْنُ جُوَيْرِيَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ ‏} ‏قَالَ يَغِيبُ أَحَدُهُمْ فِي ‏ ‏رَشْحِهِ ‏ ‏إِلَى أَنْصَافِ أُذُنَيْهِ ‏","","",""],[5561,5561,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏صَخْرٌ يَعْنِي ابْنَ جُوَيْرِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَالَ الرَّجُلُ لِصَاحِبِهِ يَا كَافِرُ فَإِنَّهَا تَجِبُ عَلَى أَحَدِهِمَا فَإِنْ كَانَ الَّذِي قِيلَ لَهُ كَافِرٌ فَهُوَ كَافِرٌ وَإِلَّا رَجَعَ إِلَيْهِ مَا قَالَ ‏","","",""],[5562,5562,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ مُحْرِزٍ ‏ ‏قَالَ ‏ ‏بَيْنَمَا ‏ ‏ابْنُ عُمَرَ ‏ ‏يَطُوفُ ‏ ‏بِالْبَيْتِ ‏ ‏إِذْ عَرَضَهُ رَجُلٌ فَقَالَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏كَيْفَ سَمِعْتَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي ‏ ‏النَّجْوَى ‏ ‏قَالَ ‏ ‏يَدْنُو الْمُؤْمِنُ مِنْ رَبِّهِ يَوْمَ الْقِيَامَةِ كَأَنَّهُ ‏ ‏بَذَجٌ ‏ ‏فَيَضَعُ عَلَيْهِ ‏ ‏كَنَفَهُ ‏ ‏أَيْ يَسْتُرُهُ ثُمَّ يَقُولُ أَتَعْرِفُ فَيَقُولُ رَبِّ أَعْرِفُ ثُمَّ يَقُولُ أَتَعْرِفُ فَيَقُولُ رَبِّ أَعْرِفُ فَيَقُولُ أَنَا سَتَرْتُهَا عَلَيْكَ فِي الدُّنْيَا وَأَنَا أَغْفِرُهَا لَكَ الْيَوْمَ وَيُعْطَى صَحِيفَةَ حَسَنَاتِهِ وَأَمَّا الْكُفَّارُ وَالْمُنَافِقُونَ فَيُنَادَى بِهِمْ عَلَى رُءُوسِ الْأَشْهَادِ هَؤُلَاءِ الَّذِينَ كَذَبُوا عَلَى رَبِّهِمْ أَلَا لَعْنَةُ اللَّهِ عَلَى الظَّالِمِينَ ‏ ‏قَالَ ‏ ‏سَعِيدٌ ‏ ‏وَقَالَ ‏ ‏قَتَادَةُ ‏ ‏فَلَمْ ‏ ‏يَخْزَ ‏ ‏يَوْمَئِذٍ أَحَدٌ فَخَفِيَ ‏ ‏خِزْيُهُ ‏ ‏عَلَى أَحَدٍ مِنْ الْخَلَائِقِ ‏","","",""],[5563,5563,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَعْدٍ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏أَنَّهُ أَبْصَرَ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يُصَلِّي عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏لِغَيْرِ الْقِبْلَةِ تَطَوُّعًا فَقَالَ مَا هَذَا يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ كَانَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُهُ ‏","","",""],[5564,5564,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا النَّاسُ يُصَلُّونَ فِي ‏ ‏مَسْجِدِ قُبَاءَ ‏ ‏إِذْ جَاءَ ‏ ‏رَجُلٌ ‏ ‏فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ أُنْزِلَ عَلَيْهِ قُرْآنٌ وَقَدْ ‏ ‏أُمِرَ أَنْ يَتَوَجَّهَ إِلَى ‏ ‏الْكَعْبَةِ ‏ ‏قَالَ فَاسْتَدَارُوا ‏","","",""],[5565,5565,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ أَحَدُكُمْ الْجُمُعَةَ فَلْيَغْتَسِلْ ‏","","",""],[5566,5566,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي الشَّعْثَاءِ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِابْنِ عُمَرَ ‏ ‏إِنَّا نَدْخُلُ عَلَى أُمَرَائِنَا فَنَقُولُ الْقَوْلَ فَإِذَا خَرَجْنَا قُلْنَا غَيْرَهُ فَقَالَ ‏ ‏كُنَّا نَعُدُّ هَذَا عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النِّفَاقَ ‏","","",""],[5567,5567,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ مُبَارَكٍ ‏ ‏أَخْبَرَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏وَنَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا ‏ ‏قَفَلَ ‏ ‏مِنْ الْغَزْوِ أَوْ الْحَجِّ أَوْ الْعُمْرَةِ يَبْدَأُ فَيُكَبِّرُ ثَلَاثَ مِرَارٍ ثُمَّ يَقُولُ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ‏ ‏آيِبُونَ ‏ ‏تَائِبُونَ عَابِدُونَ سَاجِدُونَ لِرَبِّنَا حَامِدُونَ صَدَقَ اللَّهُ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الْأَحْزَابَ وَحْدَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏وَنَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[5568,5568,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ يَعْنِي ابْنَ السَّائِبِ ‏ ‏عَنْ ‏ ‏مُحَارِبٍ يَعْنِي ابْنَ دِثَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا أَيُّهَا النَّاسُ ‏ ‏إِيَّاكُمْ وَالظُّلْمَ فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ ‏","","",""],[5569,5569,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏بَكَّارٍ يَعْنِي ابْنَ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏خَلَّادِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ جُنْدَةَ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏طَاوُسًا ‏ ‏عَنْ الشَّرَابِ ‏ ‏فَأَخْبَرَهُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْجَرِّ ‏ ‏وَالدُّبَّاءِ ‏","","",""],[5570,5570,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا طَلَعَ حَاجِبُ الشَّمْسِ فَأَخِّرُوا الصَّلَاةَ حَتَّى تَبْرُزَ وَإِذَا غَابَ حَاجِبُ الشَّمْسِ فَأَخِّرُوا الصَّلَاةَ حَتَّى تَغِيبَ ‏","","",""],[5571,5571,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏يَتَحَرَّى ‏ ‏أَحَدُكُمْ الصَّلَاةَ طُلُوعَ الشَّمْسِ وَلَا غُرُوبَهَا فَإِنَّهَا تَطْلُعُ بَيْنَ قَرْنَيْ الشَّيْطَانِ ‏","","",""],[5572,5572,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ صُبَيْحٍ الْحَنَفِيِّ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ إِلَى جَنْبِ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَوَضَعْتُ يَدِي عَلَى خَاصِرَتِي فَضَرَبَ يَدَيَّ فَلَمَّا صَلَّى قَالَ ‏ ‏هَذَا ‏ ‏الصَّلْبُ ‏ ‏فِي الصَّلَاةِ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْهُ ‏","","",""],[5573,5573,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ عُمَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمَةَ الْهُجَيْمِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏فَلَا صَلَاةَ بَعْدَ ‏ ‏الْغَدَاةِ ‏ ‏حَتَّى تَطْلُعَ الشَّمْسُ ‏","","",""],[5574,5574,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏الْعُمَرِيِّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَدَّ بِهِ السَّيْرُ جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏","","",""],[5575,5575,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَا كَانَ لِي مَبِيتٌ وَلَا مَأْوَى عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا فِي الْمَسْجِدِ ‏","","",""],[5576,5576,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏تُرْكَزُ لَهُ ‏ ‏الْحَرْبَةُ ‏ ‏فِي الْعِيدَيْنِ فَيُصَلِّي إِلَيْهَا ‏","","",""],[5577,5577,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيْكٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى إِلَى بَعِيرٍ ‏","","",""],[5578,5578,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏فُضَيْلِ بْنِ مَرْزُوقٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَجْدَةٌ مِنْ سُجُودِ هَؤُلَاءِ أَطْوَلُ مِنْ ثَلَاثِ سَجَدَاتٍ مِنْ سُجُودِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[5579,5579,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَرْفَعُ يَدَيْهِ ‏ ‏حَذْوَ ‏ ‏مَنْكِبَيْهِ ‏","","",""],[5580,5580,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي ‏ ‏أُتِيَ ‏ ‏بِفَضِيخٍ ‏ ‏فِي مَسْجِدِ ‏ ‏الْفَضِيخِ ‏ ‏فَشَرِبَهُ فَلِذَلِكَ سُمِّيَ ‏","","",""],[5581,5581,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا لَمْ يَشْرَبْهَا فِي الْآخِرَةِ ‏","","",""],[5582,5582,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ ابْنَةِ أَبِي عُبَيْدٍ ‏ ‏قَالَتْ ‏ ‏رَأَى ‏ ‏ابْنُ عُمَرَ ‏ ‏صَبِيًّا فِي رَأْسِهِ ‏ ‏قَنَازِعُ ‏ ‏فَقَالَ أَمَا عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ تَحْلِقَ الصِّبْيَانُ ‏ ‏الْقَزَعَ ‏","","",""],[5583,5583,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عُبَيْدِ اللَّهِ بْنِ عَبْدِ الِلَّهِ بْنِ عُمَرَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَكَلَ أَحَدُكُمْ أَوْ شَرِبَ فَلَا يَأْكُلْ بِشِمَالِهِ وَلَا يَشْرَبْ بِشِمَالِهِ فَإِنَّ الشَّيْطَانَ يَأْكُلُ وَيَشْرَبُ بِشِمَالِهِ ‏","","",""],[5584,5584,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏كَانَ يَسْمَعُهُ يُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَمَّرَ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏فَبَلَغَهُ أَنَّ النَّاسَ عَابُوا ‏ ‏أُسَامَةَ ‏ ‏وَطَعَنُوا فِي إِمَارَتِهِ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي النَّاسِ فَقَالَ ‏ ‏كَمَا حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏أَلَا إِنَّكُمْ تَعِيبُونَ ‏ ‏أُسَامَةَ ‏ ‏وَتَطْعَنُونَ فِي إِمَارَتِهِ وَقَدْ فَعَلْتُمْ ذَلِكَ بِأَبِيهِ مِنْ قَبْلُ وَإِنْ كَانَ ‏ ‏لَخَلِيقًا ‏ ‏لِلْإِمَارَةِ وَإِنْ كَانَ لَأَحَبَّ النَّاسِ كُلِّهِمْ إِلَيَّ وَإِنَّ ابْنَهُ هَذَا مِنْ بَعْدِهِ لَأَحَبُّ النَّاسِ إِلَيَّ ‏ ‏فَاسْتَوْصُوا بِهِ خَيْرًا فَإِنَّهُ مِنْ خِيَارِكُمْ ‏ ‏قَالَ ‏ ‏سَالِمٌ ‏ ‏مَا سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏يُحَدِّثُ هَذَا الْحَدِيثَ قَطُّ إِلَّا قَالَ ‏ ‏مَا حَاشَا ‏ ‏فَاطِمَةَ ‏","","",""],[5585,5585,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏عَنْ رُؤْيَا رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي وَبَاءِ ‏ ‏الْمَدِينَةِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ امْرَأَةً سَوْدَاءَ ثَائِرَةَ الرَّأْسِ خَرَجَتْ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏حَتَّى قَامَتْ ‏ ‏بِمَهْيَعَةَ ‏ ‏فَأَوَّلْتُ ‏ ‏أَنَّ وَبَاءَهَا نُقِلَ إِلَى ‏ ‏مَهْيَعَةَ ‏ ‏وَهِيَ ‏ ‏الْجُحْفَةُ ‏","","",""],[5586,5586,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نَهَى عَنْ بَيْعِ ‏ ‏الْوَلَاءِ ‏ ‏وَعَنْ هِبَتِهِ ‏ ‏قَالَ ‏ ‏قُلْتُ سَمِعْتَ مِنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَعَمْ وَسَأَلَهُ عَنْهُ ابْنُهُ ‏ ‏حَمْزَةُ ‏","","",""],[5587,5587,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏اتَّخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمًا مِنْ ذَهَبٍ فَاتَّخَذَ النَّاسُ خَوَاتِمَهُمْ مِنْ ذَهَبٍ فَقَامَ يَوْمًا فَقَالَ ‏ ‏إِنِّي كُنْتُ أَلْبَسُ هَذَا الْخَاتَمَ ثُمَّ ‏ ‏نَبَذَهُ ‏ ‏فَنَبَذَ ‏ ‏النَّاسُ خَوَاتِيمَهُمْ ‏","","",""],[5588,5588,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏بِلَالًا ‏ ‏يُنَادِي بِلَيْلٍ فَكُلُوا وَاشْرَبُوا حَتَّى يُنَادِيَ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏","","",""],[5589,5589,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏وَقَّتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏وَلِأَهْلِ ‏ ‏نَجْدٍ ‏ ‏قَرْنًا ‏ ‏وَلِأَهْلِ ‏ ‏الشَّامِ ‏ ‏الْجُحْفَةَ ‏ ‏وَزَعَمُوا أَنَّهُ ‏ ‏وَقَّتَ ‏ ‏لِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏يَلَمْلَمَ ‏","","",""],[5590,5590,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏قَالَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي ‏ ‏أَشْتَرِي الْبَيْعَ فَأُخْدَعُ فَقَالَ ‏ ‏إِذَا كَانَ ذَاكَ فَقُلْ لَا ‏ ‏خِلَابَةَ ‏","","",""],[5591,5591,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنِي ‏ ‏عَاصِمُ بْنُ الْمُنْذِرِ ‏ ‏قَالَ ‏ ‏كُنَّا فِي بُسْتَانٍ لَنَا ‏ ‏أَوْ ‏ ‏لِعُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏نَرْمِي فَحَضَرَتْ الصَّلَاةُ فَقَامَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏إِلَى ‏ ‏مَقْرَى ‏ ‏الْبُسْتَانِ فِيهِ جِلْدُ بَعِيرٍ فَأَخَذَ يَتَوَضَّأُ فِيهِ فَقُلْتُ أَتَتَوَضَّأُ فِيهِ وَفِيهِ هَذَا الْجِلْدُ فَقَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ الْمَاءُ ‏ ‏قُلَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا فَإِنَّهُ لَا يَنْجُسُ ‏","","",""],[5592,5592,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمَرَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏إِنَّ عِنْدَنَا رِجَالًا يَزْعُمُونَ أَنَّ الْأَمْرَ بِأَيْدِيهِمْ فَإِنْ شَاءُوا عَمِلُوا وَإِنْ شَاءُوا لَمْ يَعْمَلُوا فَقَالَ أَخْبِرْهُمْ أَنِّي مِنْهُمْ بَرِيءٌ وَأَنَّهُمْ مِنِّي بُرَآءُ ثُمَّ قَالَ جَاءَ ‏ ‏جِبْرِيلُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏مَا الْإِسْلَامُ فَقَالَ ‏ ‏تَعْبُدُ اللَّهَ لَا تُشْرِكُ بِهِ شَيْئًا وَتُقِيمُ الصَّلَاةَ وَتُؤْتِي الزَّكَاةَ وَتَصُومُ رَمَضَانَ وَتَحُجُّ ‏ ‏الْبَيْتَ ‏ ‏قَالَ فَإِذَا فَعَلْتُ ذَلِكَ فَأَنَا مُسْلِمٌ قَالَ نَعَمْ قَالَ صَدَقْتَ قَالَ فَمَا الْإِحْسَانُ قَالَ ‏ ‏تَخْشَى اللَّهَ تَعَالَى كَأَنَّكَ تَرَاهُ فَإِنْ لَا تَكُ تَرَاهُ فَإِنَّهُ يَرَاكَ قَالَ فَإِذَا فَعَلْتُ ذَلِكَ فَأَنَا مُحْسِنٌ قَالَ نَعَمْ قَالَ صَدَقْتَ قَالَ فَمَا الْإِيمَانُ قَالَ تُؤْمِنُ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْبَعْثِ مِنْ بَعْدِ الْمَوْتِ وَالْجَنَّةِ وَالنَّارِ وَالْقَدَرِ كُلِّهِ قَالَ فَإِذَا فَعَلْتُ ذَلِكَ فَأَنَا مُؤْمِنٌ قَالَ نَعَمْ قَالَ صَدَقْتَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمَرَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏يَأْتِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي صُورَةِ دِحْيَةَ ‏","","",""],[5593,5593,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمُ ‏ ‏سَالَمَهَا اللَّهُ ‏ ‏وَغِفَارٌ ‏ ‏غَفَرَ اللَّهُ لَهَا ‏","","",""],[5594,5594,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏صَخْرٌ يَعْنِي ابْنَ جُوَيْرِيَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا أَنَا عَلَى بِئْرٍ أَنْزِعُ مِنْهَا إِذْ جَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏فَأَخَذَ ‏ ‏أَبُو بَكْرٍ ‏ ‏الدَّلْوَ فَنَزَعَ ذَنُوبًا أَوْ ذَنُوبَيْنِ وَفِي نَزْعِهِ ضَعْفٌ وَاللَّهُ يَغْفِرُ لَهُ ثُمَّ أَخَذَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏مِنْ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَاسْتَحَالَتْ ‏ ‏فِي يَدِهِ ‏ ‏غَرْبًا ‏ ‏فَلَمْ أَرَ عَبْقَرِيًّا مِنْ النَّاسِ ‏ ‏يَفْرِي ‏ ‏فَرِيَّهُ ‏ ‏حَتَّى ضَرَبَ النَّاسُ بِعَطَنٍ ‏","","",""],[5595,5595,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَأْتِي ‏ ‏قُبَاءَ ‏ ‏رَاكِبًا وَمَاشِيًا ‏","","",""],[5596,5596,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ابْتَاعَ طَعَامًا فَلَا يَبِعْهُ حَتَّى يَقْبِضَهُ ‏","","",""],[5597,5597,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِدْرِيسَ الشَّافِعِيُّ ‏ ‏رَحِمَهُ اللَّهُ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ وَنَهَى عَنْ ‏ ‏النَّجْشِ ‏ ‏وَنَهَى عَنْ بَيْعِ ‏ ‏حَبَلِ الْحَبَلَةِ ‏ ‏وَنَهَى عَنْ ‏ ‏الْمُزَابَنَةِ ‏ ‏وَالْمُزَابَنَةُ ‏ ‏بَيْعُ الثَّمَرِ بِالتَّمْرِ كَيْلًا وَبَيْعُ الْكَرْمِ بِالزَّبِيبِ كَيْلًا ‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏النَّجْشِ ‏ ‏مِثْلَهُ ‏","","",""],[5598,5598,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ ‏ ‏بِحَدِّ ‏ ‏الشِّفَارِ ‏ ‏وَأَنْ ‏ ‏تُوَارَى ‏ ‏عَنْ الْبَهَائِمِ وَإِذَا ذَبَحَ أَحَدُكُمْ فَلْيُجْهِزْ ‏","","",""],[5599,5599,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَلَيْكُمْ بِالسِّوَاكِ فَإِنَّهُ مَطْيَبَةٌ لِلْفَمِ وَمَرْضَاةٌ لِلرَّبِّ ‏","","",""],[5600,5600,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ يُحِبُّ أَنْ تُؤْتَى رُخَصُهُ كَمَا يَكْرَهُ أَنْ تُؤْتَى مَعْصِيَتُهُ ‏","","",""]];
